-- Tabla: fza_articulos_stockactual
DROP TABLE IF EXISTS fza_articulos_stockactual CASCADE;
CREATE TABLE fza_articulos_stockactual (
  CODIGO_ALMACEN_STK varchar(10) NOT NULL,
  CODIGO_UNIDAD_STK varchar(50) NOT NULL,
  LOTE_STK varchar(50) NOT NULL DEFAULT '',
  FECHA_CADUCIDAD_STK date NULL DEFAULT NULL,
  CANTIDAD_STK numeric(19,6) NULL DEFAULT '0.000000',
  INSTANTEMODIF timestamp without time zone NOT NULL DEFAULT statement_timestamp(),
  VALOR_TOTAL_STK numeric(19,6) NULL DEFAULT '0.000000',
  PRECIO_MEDIO_STK numeric(19,6) NULL DEFAULT '0.000000',
  CANTIDAD_PTE_RECIBIR numeric(19,6) NULL DEFAULT '0.000000',
  CANTIDAD_PTE_SERVIR numeric(19,6) NULL DEFAULT '0.000000',
  CANTIDAD_PTE_TRASPASAR numeric(19,6) NULL DEFAULT '0.000000',
  CANTIDAD_PTE_RECTRASPASAR numeric(19,6) NULL DEFAULT '0.000000',
  PRIMARY KEY (CODIGO_ALMACEN_STK,CODIGO_UNIDAD_STK,LOTE_STK)
);
