-- Tabla: fza_articulos_tarifas
DROP TABLE IF EXISTS fza_articulos_tarifas CASCADE;
CREATE TABLE fza_articulos_tarifas (
  CODIGO_ARTICULO_TARIFA varchar(20) NOT NULL,
  CODIGO_UNICO_TARIFA integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  CODIGO_UNIDAD_TARIFA varchar(50) NOT NULL DEFAULT '',
  CODIGO_TARIFA varchar(10) NULL DEFAULT NULL,
  ACTIVO_TARIFA varchar(1) NULL DEFAULT 'S',
  PRECIOSALIDA_TARIFA numeric(19,6) NULL DEFAULT NULL,
  PRECIOFINAL_TARIFA numeric(19,6) NULL DEFAULT '0.000000',
  PRECIO_DTO_TARIFA numeric(19,6) NULL DEFAULT NULL,
  PORCEN_DTO_TARIFA numeric(19,6) NULL DEFAULT NULL,
  FECHA_DESDE_TARIFA date NULL DEFAULT NULL,
  FECHA_HASTA_TARIFA date NULL DEFAULT NULL,
  INSTANTEMODIF timestamp without time zone NOT NULL DEFAULT statement_timestamp(),
  INSTANTEALTA timestamp without time zone NOT NULL DEFAULT TIMESTAMP '1970-01-01 00:00:00',
  USUARIOALTA varchar(100) NOT NULL,
  USUARIOMODIF varchar(100) NOT NULL,
  PRIMARY KEY (CODIGO_UNICO_TARIFA)
);
CREATE INDEX idx_art_tarifas_busqueda ON fza_articulos_tarifas (CODIGO_ARTICULO_TARIFA, CODIGO_TARIFA);
