-- Tabla: fza_articulos_vinculos
DROP TABLE IF EXISTS fza_articulos_vinculos CASCADE;
CREATE TABLE fza_articulos_vinculos (
  ID_VINCULO integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  CODIGO_ARTICULO_PADRE varchar(20) NOT NULL,
  CODIGO_ARTICULO_HIJO varchar(20) NOT NULL,
  CANTIDAD numeric(10,2) NULL DEFAULT '1.00',
  ORDEN_VISUAL integer NULL DEFAULT '1',
  ES_OBLIGATORIO char(1) NULL DEFAULT 'S',
  PRIMARY KEY (ID_VINCULO)
);
