-- Tabla: fza_atributos_basicos
DROP TABLE IF EXISTS fza_atributos_basicos CASCADE;
CREATE TABLE fza_atributos_basicos (
  ID_BASICO integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  ID_VA_BASICO varchar(20) NOT NULL,
  CODIGO_BASICO varchar(30) NOT NULL,
  NOMBRE_BASICO varchar(100) NOT NULL,
  EXTRA_BASICO varchar(7) NULL DEFAULT NULL,
  ORDEN_BASICO integer NULL DEFAULT '0',
  ESACTIVO_BASICO char(1) NULL DEFAULT 'S',
  PRIMARY KEY (ID_BASICO)
);
CREATE UNIQUE INDEX id_va_basico ON fza_atributos_basicos (ID_VA_BASICO, CODIGO_BASICO);

