-- Tabla: fza_atributos_valores
DROP TABLE IF EXISTS fza_atributos_valores CASCADE;
CREATE TABLE fza_atributos_valores (
  ID_VALOR_AV integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  ID_VA_AV varchar(20) NOT NULL,
  VALOR_AV varchar(100) NOT NULL,
  ORDEN_AV integer NOT NULL DEFAULT '0',
  DESCRIPCION_AV varchar(255) NULL DEFAULT NULL,
  ESACTIVO_AV varchar(1) NULL DEFAULT 'S',
  FACTOR_CONVERSION_AV numeric(19,6) NULL DEFAULT '1.000000',
  UNIDAD_MEDIDA_AV varchar(10) NULL DEFAULT NULL,
  CODIGO_ARTICULO_EXTRA varchar(20) NULL DEFAULT NULL,
  INSTANTEMODIF timestamp without time zone NOT NULL DEFAULT statement_timestamp(),
  INSTANTEALTA timestamp without time zone NOT NULL DEFAULT TIMESTAMP '1970-01-01 00:00:00',
  USUARIOALTA varchar(100) NOT NULL,
  USUARIOMODIF varchar(100) NOT NULL,
  PRIMARY KEY (ID_VALOR_AV)
);
CREATE INDEX idx_var_av ON fza_atributos_valores (ID_VA_AV);
