-- Tabla: fza_caja_formas_pago
DROP TABLE IF EXISTS fza_caja_formas_pago CASCADE;
CREATE TABLE fza_caja_formas_pago (
  CODIGO_FORMAP varchar(20) NOT NULL,
  DESCRIPCION_FORMAP varchar(100) NOT NULL,
  ES_REQ_REFERENCIA_FORMAP varchar(1) NOT NULL DEFAULT 'N',
  ES_CRIPTO_FORMAP varchar(1) NOT NULL,
