  HASH_BOCKCHAIN_FORMAP varchar(128) NULL DEFAULT NULL,
  ESDIVISA_FORMAP varchar(1) NOT NULL,
  ES_DEVUELVE_CAMBIO_FORMAP varchar(1) NULL DEFAULT 'S',
  ES_ABRE_CAJON_FORMAP varchar(1) NULL DEFAULT 'N',
  ES_ACTIVO_FORMAP varchar(1) NULL DEFAULT 'S',
