-- Tabla: fza_caja_operaciones
DROP TABLE IF EXISTS fza_caja_operaciones CASCADE;
CREATE TABLE fza_caja_operaciones (
  ID_OPCAJA bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  CODIGO_EMPRESA_OPCAJA varchar(10) NOT NULL,
  CODIGO_ALMACEN_OPCAJA varchar(10) NOT NULL,
  CODIGO_CAJA_OPCAJA varchar(10) NOT NULL,
  NUMERO_OPERACION_OPCAJA varchar(20) NOT NULL,
  NRO_FACTURA_OPCAJA varchar(20) NULL DEFAULT NULL,
  SERIE_FACTURA_OPCAJA varchar(20) NULL DEFAULT NULL,
  FECHA_OPERACION_OPCAJA timestamp without time zone NOT NULL,
  CODIGO_EMPLEADO_OPCAJA varchar(20) NOT NULL,
  TIPO_OPERACION_OPCAJA varchar(2) NOT NULL,
  IMPORTE_TOTAL_OPCAJA numeric(19,6) NOT NULL DEFAULT '0.000000',
  CODIGO_CLIENTE_OPCAJA varchar(20) NULL DEFAULT NULL,
  ESTADO_DEVOLUCION_OPCAJA char(1) NOT NULL DEFAULT 'N',
  IMPORTE_DEVUELTO_ACUM_OPCAJA numeric(19,6) NOT NULL DEFAULT '0.000000',
  CONCEPTO_GASTO_INGRESO_OPCAJA varchar(100) NULL DEFAULT NULL,
  SERIE_REF_ORIGEN_OPCAJA varchar(20) NULL DEFAULT NULL,
  NUMERO_REF_ORIGEN_OPCAJA varchar(20) NULL DEFAULT NULL,
  MOTIVO_DEVOLUCION_OPCAJA varchar(50) NULL DEFAULT NULL,
  CODIGO_EMPRESA_CONTRA_OPCAJA varchar(20) NULL DEFAULT NULL,
  CODIGO_ALMACEN_CONTRA_OPCAJA varchar(10) NULL DEFAULT NULL,
  ES_TRASPASO_OPCAJA varchar(1) NULL DEFAULT 'N',
  CODIGO_ARQUEO_OPCAJA varchar(20) NULL DEFAULT NULL,
  INSTANTEMODIF timestamp without time zone NOT NULL DEFAULT statement_timestamp(),
  INSTANTEALTA timestamp without time zone NOT NULL DEFAULT TIMESTAMP '1970-01-01 00:00:00',
  USUARIOALTA varchar(100) NOT NULL,
  USUARIOMODIF varchar(100) NOT NULL,
  ID_DEPOSITO_OPCAJA varchar(20) NULL DEFAULT NULL,
  FECHA_OP_DIA date NULL DEFAULT NULL,
  PRIMARY KEY (ID_OPCAJA)
);
CREATE INDEX ft_opcaja_concepto ON fza_caja_operaciones (CONCEPTO_GASTO_INGRESO_OPCAJA);
CREATE INDEX idx_agrupacion_opcaja ON fza_caja_operaciones (CODIGO_EMPRESA_OPCAJA, CODIGO_ALMACEN_OPCAJA, CODIGO_CAJA_OPCAJA, NUMERO_OPERACION_OPCAJA);
CREATE INDEX idx_cierre_opcaja ON fza_caja_operaciones (CODIGO_ARQUEO_OPCAJA);
CREATE INDEX idx_dep_opcaja ON fza_caja_operaciones (ID_DEPOSITO_OPCAJA);
CREATE INDEX idx_opcaja_ctx_fecha ON fza_caja_operaciones (CODIGO_EMPRESA_OPCAJA, CODIGO_ALMACEN_OPCAJA, CODIGO_CAJA_OPCAJA, FECHA_OPERACION_OPCAJA);
CREATE INDEX idx_opcaja_dia_ctx ON fza_caja_operaciones (FECHA_OP_DIA, CODIGO_EMPRESA_OPCAJA, CODIGO_ALMACEN_OPCAJA, CODIGO_CAJA_OPCAJA);
CREATE INDEX idx_ref_origen_opcaja ON fza_caja_operaciones (SERIE_REF_ORIGEN_OPCAJA, NUMERO_REF_ORIGEN_OPCAJA);
