-- Tabla: fza_caja_pagos
DROP TABLE IF EXISTS fza_caja_pagos CASCADE;
CREATE TABLE fza_caja_pagos (
  CODIGO_EMPRESA_PAGO varchar(20) NOT NULL,
  CODIGO_ALMACEN_PAGO varchar(10) NOT NULL,
  CODIGO_CAJA_PAGO varchar(10) NOT NULL,
  SERIE_OPERACION_PAGO varchar(20) NOT NULL,
  NUMERO_OPERACION_PAGO varchar(20) NOT NULL,
  NUMERO_LINEA_PAGO integer NOT NULL DEFAULT '1',
  CODIGO_FORMAP varchar(10) NOT NULL,
  CODIGO_DIVISA_PAGO varchar(10) NULL DEFAULT NULL,
  RED_BLOCKCHAIN varchar(50) NULL DEFAULT NULL,
  FACTOR_CAMBIO_PAGO numeric(24,8) NOT NULL DEFAULT '1.00000000',
  IMPORTE_DIVISA_PAGO numeric(24,8) NOT NULL DEFAULT '0.00000000',
  IMPORTE_ENTREGADO_PAGO numeric(19,6) NOT NULL DEFAULT '0.000000',
  IMPORTE_CAMBIO_PAGO numeric(19,6) NOT NULL DEFAULT '0.000000',
  REFERENCIA_PAGO varchar(255) NULL DEFAULT NULL,
  OBSERVACIONES_PAGO varchar(255) NULL DEFAULT NULL,
  INSTANTEMODIF timestamp without time zone NOT NULL DEFAULT statement_timestamp(),
  INSTANTEALTA timestamp without time zone NOT NULL DEFAULT TIMESTAMP '1970-01-01 00:00:00',
  USUARIOALTA varchar(100) NOT NULL,
  PRIMARY KEY (CODIGO_EMPRESA_PAGO,CODIGO_ALMACEN_PAGO,CODIGO_CAJA_PAGO,SERIE_OPERACION_PAGO,NUMERO_OPERACION_PAGO,NUMERO_LINEA_PAGO)
