-- Tabla: fza_clientes
DROP TABLE IF EXISTS fza_clientes CASCADE;
CREATE TABLE fza_clientes (
  CODIGO_CLIENTE varchar(10) NOT NULL,
  ACTIVO_CLIENTE varchar(1) NULL DEFAULT 'S',
  ORDEN_CLIENTE integer NULL DEFAULT NULL,
  RAZONSOCIAL_CLIENTE varchar(200) NOT NULL,
  NIF_CLIENTE varchar(50) NULL DEFAULT NULL,
  MOVIL_CLIENTE varchar(40) NULL DEFAULT NULL,
  EMAIL_CLIENTE varchar(200) NULL DEFAULT NULL,
  DIRECCION1_CLIENTE varchar(200) NULL DEFAULT NULL,
  DIRECCION2_CLIENTE varchar(200) NULL DEFAULT NULL,
  POBLACION_CLIENTE varchar(200) NULL DEFAULT NULL,
  PROVINCIA_CLIENTE varchar(200) NULL DEFAULT NULL,
  CPOSTAL_CLIENTE varchar(15) NULL DEFAULT NULL,
  CODIGO_PAIS_CLIENTE varchar(3) NULL DEFAULT '724',
  NOMBRE_PAIS_CLIENTE varchar(150) NULL DEFAULT 'España',
  OBSERVACIONES_CLIENTE text NULL DEFAULT NULL,
  REFERENCIA_CLIENTE varchar(100) NULL DEFAULT NULL,
  CONTACTO_CLIENTE varchar(100) NULL DEFAULT NULL,
  TELEFONO_CONTACTO_CLIENTE varchar(100) NULL DEFAULT NULL,
  TELEFONO_CLIENTE varchar(40) NULL DEFAULT NULL,
  IBAN_CLIENTE varchar(100) NULL DEFAULT NULL,
  ESIVA_RECARGO_CLIENTE varchar(1) NULL DEFAULT 'N',
  ESRETENCIONES_CLIENTE varchar(1) NULL DEFAULT 'S',
  TOTAL_LIMITE_CREDITO_CLIENTE numeric(19,6) NULL DEFAULT NULL,
  ESPERMITE_DEUDA_CLIENTE varchar(1) NULL DEFAULT NULL,
  TOTAL_DEUDA_CLIENTE numeric(19,6) NULL DEFAULT NULL,
  ESIVA_EXENTO_CLIENTE varchar(1) NULL DEFAULT 'N',
  ESINTRACOMUNITARIO_CLIENTE varchar(1) NULL DEFAULT 'N',
  ESREGIMENESPECIALAGRICOLA_CLIENTE varchar(1) NULL DEFAULT 'N',
  CODIGO_FORMA_PAGO_CLIENTE varchar(20) NULL DEFAULT NULL,
  TARIFA_ARTICULO_CLIENTE varchar(10) NULL DEFAULT NULL,
  SERIE_CONTADOR_CLIENTE varchar(8) NULL DEFAULT NULL,
  TEXTO_LEGAL_FACTURA_CLIENTE varchar(1000) NULL DEFAULT NULL,
  INSTANTEMODIF timestamp without time zone NOT NULL DEFAULT statement_timestamp(),
  INSTANTEALTA timestamp without time zone NOT NULL DEFAULT TIMESTAMP '1970-01-01 00:00:00',
  USUARIOALTA varchar(100) NOT NULL,
  USUARIOMODIF varchar(100) NOT NULL,
  PRIMARY KEY (CODIGO_CLIENTE)
);
CREATE INDEX ft_cli_razon ON fza_clientes (RAZONSOCIAL_CLIENTE);
CREATE INDEX idx_clientes_email ON fza_clientes (EMAIL_CLIENTE);
CREATE INDEX idx_clientes_listado ON fza_clientes (CODIGO_CLIENTE, RAZONSOCIAL_CLIENTE);
CREATE INDEX idx_nif_cliente ON fza_clientes (EMAIL_CLIENTE);
CREATE INDEX idx_poblacion_cliente ON fza_clientes (NIF_CLIENTE);
CREATE INDEX idx_razonsocial_cliente ON fza_clientes (RAZONSOCIAL_CLIENTE);
CREATE INDEX idx_referencia_cliente ON fza_clientes (REFERENCIA_CLIENTE);
