CREATE TABLE fza_depositos_cliente (
  ID_DEPOSITO_DEP varchar(20) NOT NULL,
  CODIGO_EMPRESA_DEP varchar(20) NOT NULL,
  CODIGO_CLIENTE_DEP varchar(20) NOT NULL,
  CODIGO_ARTICULO_DEP varchar(50) NOT NULL,
