  DIRECCION2_CLIENTE_FACTURA varchar(200) NULL DEFAULT NULL,
  POBLACION_CLIENTE_FACTURA varchar(200) NULL DEFAULT NULL,
  PROVINCIA_CLIENTE_FACTURA varchar(200) NULL DEFAULT NULL,
  CPOSTAL_CLIENTE_FACTURA varchar(15) NULL DEFAULT NULL,
  CODIGO_PAIS_CLIENTE_FACTURA varchar(3) NULL DEFAULT '724',
  NOMBRE_PAIS_CLIENTE_FACTURA varchar(150) NULL DEFAULT 'España',
  CODIGO_IVA_FACTURA varchar(20) NULL DEFAULT NULL,
  ESIVA_RECARGO_CLIENTE_FACTURA varchar(1) NULL DEFAULT 'N',
  ESIVA_EXENTO_CLIENTE_FACTURA varchar(1) NULL DEFAULT 'N',
