  ESRETENCIONES_CLIENTE_FACTURA varchar(1) NULL DEFAULT 'S',
  TARIFA_ARTICULO_CLIENTE_FACTURA varchar(10) NULL DEFAULT NULL,
  ESIMP_INCL_TARIFA_CLIENTE_FACTURA varchar(1) NULL DEFAULT 'S',
  ESINTRACOMUNITARIO_CLIENTE_FACTURA varchar(1) NULL DEFAULT 'N',
  ESIRPF_IMP_INCL_ZONA_IVA_FACTURA varchar(1) NULL DEFAULT 'N',
  ESAPLICA_RE_ZONA_IVA_FACTURA varchar(1) NULL DEFAULT 'S',
  ESIVAAGRICOLA_ZONA_IVA_FACTURA varchar(1) NULL DEFAULT 'N',
  PALABRA_REPORTS_ZONA_IVA_FACTURA varchar(10) NULL DEFAULT 'IVA',
  ESVENTA_ACTIVO_FIJO_FACTURA varchar(1) NULL DEFAULT 'N',
  PORCEN_IVAN_FACTURA numeric(19,6) NULL DEFAULT NULL,
  TOTAL_IVAN_FACTURA numeric(18,6) NULL DEFAULT NULL,
  PORCEN_REN_FACTURA numeric(19,6) NULL DEFAULT NULL,
  TOTAL_REN_FACTURA numeric(19,6) NULL DEFAULT NULL,
  TOTAL_BASEI_IVAN_FACTURA numeric(18,6) NULL DEFAULT NULL,
  PORCEN_IVAR_FACTURA numeric(19,6) NULL DEFAULT NULL,
  TOTAL_IVAR_FACTURA numeric(18,6) NULL DEFAULT NULL,
  PORCEN_RER_FACTURA numeric(19,6) NULL DEFAULT NULL,
  TOTAL_RER_FACTURA numeric(19,6) NULL DEFAULT NULL,
  TOTAL_BASEI_IVAR_FACTURA numeric(18,6) NULL DEFAULT NULL,
  PORCEN_IVAS_FACTURA numeric(19,6) NULL DEFAULT NULL,
  TOTAL_IVAS_FACTURA numeric(18,6) NULL DEFAULT NULL,
  PORCEN_RES_FACTURA numeric(19,6) NULL DEFAULT NULL,
  TOTAL_RES_FACTURA numeric(19,6) NULL DEFAULT NULL,
  TOTAL_BASEI_IVAS_FACTURA numeric(18,6) NULL DEFAULT NULL,
  PORCEN_IVAE_FACTURA numeric(19,6) NULL DEFAULT NULL,
  TOTAL_IVAE_FACTURA numeric(18,6) NULL DEFAULT NULL,
  PORCEN_REE_FACTURA numeric(19,6) NULL DEFAULT NULL,
  TOTAL_REE_FACTURA numeric(19,6) NULL DEFAULT NULL,
  TOTAL_BASEI_IVAE_FACTURA numeric(18,6) NULL DEFAULT NULL,
  TOTAL_BASES_FACTURA numeric(18,6) NULL DEFAULT NULL,
  TOTAL_IMPUESTOS_FACTURA numeric(18,6) NULL DEFAULT NULL,
  FORMA_PAGO_FACTURA varchar(200) NULL DEFAULT NULL,
  PORCEN_RETENCION_FACTURA numeric(19,6) NULL DEFAULT NULL,
  TOTAL_RETENCION_FACTURA numeric(18,6) NULL DEFAULT NULL,
  TOTAL_LIQUIDO_FACTURA numeric(18,6) NULL DEFAULT NULL,
  NRO_FACTURA_ABONO_FACTURA varchar(8) NULL DEFAULT NULL,
  SERIE_FACTURA_ABONO_FACTURA varchar(8) NULL DEFAULT NULL,
  TEXTO_LEGAL_FACTURA_CLIENTE_FACTURA varchar(1000) NULL DEFAULT '',
  TEXTO_LEGAL_FACTURA_EMPRESA_FACTURA varchar(1000) NULL DEFAULT '',
  DOCUMENTO_FACTURA bytea NULL DEFAULT NULL,
  COMENTARIOS_FACTURA varchar(1000) NULL DEFAULT '',
  CONTADOR_LINEAS_FACTURA varchar(8) NULL DEFAULT NULL,
  ESCREARARTICULOS_FACTURA varchar(1) NULL DEFAULT NULL,
  ESDESCRIPCIONES_AMP_FACTURA varchar(1) NULL DEFAULT 'S',
  ESFECHADEENTREGA_FACTURA varchar(1) NULL DEFAULT NULL,
  XML_FACTURA text NULL DEFAULT NULL,
  INSTANTEMODIF timestamp without time zone NOT NULL DEFAULT statement_timestamp(),
