  USUARIOALTA varchar(100) NOT NULL,
  USUARIOMODIF varchar(100) NOT NULL,
  CODIGO_CAJERO_FACTURA varchar(10) NULL DEFAULT NULL,
  CODIGO_ALMACEN_FACTURA varchar(10) NULL DEFAULT NULL,
  CODIGO_CAJA_FACTURA varchar(10) NULL DEFAULT NULL,
  NUMERO_OPERACION_FACTURA varchar(20) NULL DEFAULT NULL,
  PRIMARY KEY (NRO_FACTURA,SERIE_FACTURA)
);
