-- Tabla: fza_facturas_consolidaciones
DROP TABLE IF EXISTS fza_facturas_consolidaciones CASCADE;
CREATE TABLE fza_facturas_consolidaciones (
  ID_CONSOLIDACION integer NOT NULL,
  SERIE_FACTURA_CONSOLIDACION varchar(20) NOT NULL,
  NRO_FACTURA_CONSOLIDACION varchar(20) NOT NULL,
  REQUEST_ID_CONSOLIDACION varchar(100) NULL DEFAULT NULL,
  QUEUE_ID_CONSOLIDACION integer NULL DEFAULT NULL,
  QUEUE_ID_CANCEL_CONSOLIDACION integer NULL DEFAULT NULL,
  ISSUER_IRS_ID_CONSOLIDACION varchar(50) NULL DEFAULT NULL,
  ISSUED_TIME_CONSOLIDACION timestamp without time zone NULL DEFAULT NULL,
  CHAIN_NUMBER_CONSOLIDACION varchar(100) NULL DEFAULT NULL,
  CHAIN_HASH_CONSOLIDACION varchar(256) NULL DEFAULT NULL,
  VERIFACTU_URL_CONSOLIDACION text NULL DEFAULT NULL,
  QRCODE_BASE64_CONSOLIDACION text NULL DEFAULT NULL,
  QRCODE_PNG_CONSOLIDACION bytea NULL DEFAULT NULL,
  FECHA_PROCESAMIENTO_CONSOLIDACION timestamp without time zone NULL DEFAULT statement_timestamp(),
  ESTADO_CONSOLIDACION varchar(20) NULL DEFAULT 'PROCESADO',
  RESPUESTA_COMPLETA_CONSOLIDACION text NULL DEFAULT NULL,
  PETICION_COMPLETA_CONSOLIDACION text NULL DEFAULT NULL,
  PRIMARY KEY (ID_CONSOLIDACION)
);
CREATE INDEX idx_fecha_procesamiento_consolidacion ON fza_facturas_consolidaciones (FECHA_PROCESAMIENTO_CONSOLIDACION);
CREATE INDEX idx_request_id ON fza_facturas_consolidaciones (REQUEST_ID_CONSOLIDACION);
CREATE UNIQUE INDEX uk_factura ON fza_facturas_consolidaciones (SERIE_FACTURA_CONSOLIDACION, NRO_FACTURA_CONSOLIDACION);

-- Tabla: fza_facturas_lineas
DROP TABLE IF EXISTS fza_facturas_lineas CASCADE;
CREATE TABLE fza_facturas_lineas (
  NRO_FACTURA_LINEA varchar(20) NOT NULL,
  SERIE_FACTURA_LINEA varchar(20) NOT NULL,
  CODIGO_EMPRESA_FACTURA_LINEA varchar(8) NULL DEFAULT NULL,
  LINEA_FACTURA_LINEA varchar(4) NOT NULL,
  CODIGO_ARTICULO_FACTURA_LINEA varchar(20) NULL DEFAULT NULL,
  CODIGO_UNIDAD_FACTURA_LINEA varchar(50) NULL DEFAULT NULL,
  LOTE_FACTURA_LINEA varchar(50) NULL DEFAULT NULL,
  FECHA_CADUCIDAD_FACTURA_LINEA date NULL DEFAULT NULL,
  CODIGO_FAMILIA_FACTURA_LINEA varchar(20) NULL DEFAULT NULL,
  NOMBRE_FAMILIA_FACTURA_LINEA varchar(200) NULL DEFAULT NULL,
  PRECIO_ULT_COMPRA_FACTURA_LINEA numeric(19,6) NULL DEFAULT NULL,
  CODIGO_PROVEEDOR_FACTURA_LINEA varchar(20) NULL DEFAULT NULL,
  RAZONSOCIAL_PROVEEDOR_FACTURA_LINEA varchar(200) NULL DEFAULT NULL,
  ESPROVEEDORPRINCIPAL_FACTURA_LINEA varchar(1) NULL DEFAULT NULL,
  FECHA_ENTREGA_FACTURA_LINEA timestamp without time zone NULL DEFAULT NULL,
  TIPO_ARTICULO_FACTURA_LINEA varchar(10) NULL DEFAULT 'ESTANDAR',
  TIPO_CANTIDAD_ARTICULO_FACTURA_LINEA varchar(20) NULL DEFAULT 'Uds',
  CANTIDAD_FACTURA_LINEA numeric(19,6) NULL DEFAULT '1.000000',
  DESCRIPCION_ARTICULO_FACTURA_LINEA varchar(100) NULL DEFAULT NULL,
  DESCRIPCION_VARIACION_FACTURA_LINEA varchar(200) NULL DEFAULT NULL,
  CODIGO_TARIFA_FACTURA_LINEA varchar(10) NULL DEFAULT NULL,
  ESIMP_INCL_TARIFA_FACTURA_LINEA varchar(1) NULL DEFAULT 'S',
  PRECIOSALIDA_FACTURA_LINEA numeric(19,6) NULL DEFAULT NULL,
  PORCEN_DTO_FACTURA_LINEA numeric(19,6) NULL DEFAULT NULL,
  PRECIO_DTO_FACTURA_LINEA numeric(19,6) NULL DEFAULT NULL,
  PRECIOVENTA_SIVA_ARTICULO_FACTURA_LINEA numeric(19,6) NULL DEFAULT '0.000000',
  TIPOIVA_ARTICULO_FACTURA_LINEA varchar(2) NULL DEFAULT 'N',
  PORCEN_IVA_FACTURA_LINEA numeric(19,6) NULL DEFAULT '0.000000',
  PRECIOVENTA_CIVA_ARTICULO_FACTURA_LINEA numeric(19,6) NULL DEFAULT '0.000000',
  TOTAL_FACTURA_LINEA numeric(19,6) NULL DEFAULT '0.000000',
  TOTAL_FACTURASIVA_LINEA numeric(19,6) NULL DEFAULT NULL,
  CODIGO_VENDEDOR_FACTURA_LINEA varchar(10) NULL DEFAULT NULL,
  INSTANTEMODIF timestamp without time zone NOT NULL DEFAULT statement_timestamp(),
  INSTANTEALTA timestamp without time zone NOT NULL DEFAULT TIMESTAMP '1970-01-01 00:00:00',
  USUARIOALTA varchar(100) NOT NULL,
  USUARIOMODIF varchar(100) NOT NULL,
  CODIGO_ALMACEN_FACTURA_LINEA varchar(10) NULL DEFAULT NULL,
  CODIGO_CAJA_FACTURA_LINEA varchar(10) NULL DEFAULT NULL,
  NUMERO_OPERACION_FACTURA_LINEA varchar(20) NULL DEFAULT NULL,
  NUMERO_MOV_FACTURA_LINEA varchar(20) NULL DEFAULT NULL,
  PRIMARY KEY (NRO_FACTURA_LINEA,SERIE_FACTURA_LINEA,LINEA_FACTURA_LINEA)
);
CREATE INDEX ft_faclin_desc ON fza_facturas_lineas (DESCRIPCION_ARTICULO_FACTURA_LINEA);
CREATE INDEX idx_faclin_operacion ON fza_facturas_lineas (CODIGO_EMPRESA_FACTURA_LINEA, CODIGO_ALMACEN_FACTURA_LINEA, CODIGO_CAJA_FACTURA_LINEA, NUMERO_OPERACION_FACTURA_LINEA);
CREATE INDEX idx_fac_lin_articulo ON fza_facturas_lineas (CODIGO_ARTICULO_FACTURA_LINEA, SERIE_FACTURA_LINEA);
CREATE INDEX idx_fac_lin_familia ON fza_facturas_lineas (CODIGO_FAMILIA_FACTURA_LINEA);
