-- Tabla: fza_facturas_pagos
DROP TABLE IF EXISTS fza_facturas_pagos CASCADE;
CREATE TABLE fza_facturas_pagos (
  SERIE_FACTURA_PAGO varchar(20) NOT NULL,
  NRO_FACTURA_PAGO varchar(20) NOT NULL,
  LINEA_PAGO integer NOT NULL,
  TIPO_PAGO varchar(50) NULL DEFAULT 'EFECTIVO',
  IMPORTE_PAGO numeric(19,6) NOT NULL DEFAULT '0.000000',
  REFERENCIA_PAGO varchar(100) NULL DEFAULT NULL,
  DESCRIPCION_PAGO varchar(200) NULL DEFAULT NULL,
  ENTIDAD_PAGO varchar(100) NULL DEFAULT NULL,
  FECHA_PAGO timestamp without time zone NULL DEFAULT NULL,
  INSTANTEMODIF timestamp without time zone NOT NULL DEFAULT statement_timestamp(),
  INSTANTEALTA timestamp without time zone NOT NULL DEFAULT TIMESTAMP '1970-01-01 00:00:00',
  USUARIOALTA varchar(100) NOT NULL,
  USUARIOMODIF varchar(100) NOT NULL,
  PRIMARY KEY (SERIE_FACTURA_PAGO,NRO_FACTURA_PAGO,LINEA_PAGO)
);
CREATE INDEX idx_fecha_pago ON fza_facturas_pagos (FECHA_PAGO);
CREATE INDEX idx_tipo_pago ON fza_facturas_pagos (TIPO_PAGO);
