ALTER TABLE `fza_caja_operaciones` ADD INDEX `IDX_AGRUPACION_OPCAJA` (`CODIGO_EMPRESA_OPCAJA`, `CODIGO_ALMACEN_OPCAJA`, `CODIGO_CAJA_OPCAJA`, `NUMERO_OPERACION_OPCAJA`);', '2026-04-02 19:06:21', '2026-04-02 19:06:21', 'Administrador', 'Administrador'),
  ('075', NULL, 'DELIMITER //

CREATE OR REPLACE PROCEDURE `PRC_GET_NEXT_OP_CAJA`(
    IN  pEmpresa  VARCHAR(10),
    IN  pAlmacen  VARCHAR(10),
    IN  pCaja     VARCHAR(10),
    IN  pUsuario  VARCHAR(100),
    OUT pSerie    VARCHAR(12),
    OUT pcont     VARCHAR(20)
)
BEGIN    
    DECLARE pPADD    BIGINT;
    DECLARE vSerie   VARCHAR(12);

    START TRANSACTION;

        /* 1. Obtener serie vigente */        
        SELECT SERIE_SERIE          
          INTO vSerie          
          FROM fza_empresas_series         
         WHERE TIPODOC_SERIE        = ''OV''           
           AND CODIGO_EMPRESA_SERIE = pEmpresa           
           AND CODIGO_ALMACEN_SERIE = pAlmacen           
           AND CODIGO_CAJA_SERIE    = pCaja           
           AND FECHA_DESDE_SERIE   <= CURDATE()
           AND (FECHA_HASTA_SERIE  >= CURDATE() OR FECHA_HASTA_SERIE IS NULL)
         LIMIT 1;

        /* 2. Crear serie si no existe (Sustituye el bloque de Error) */
        IF vSerie IS NULL THEN            
            SET vSerie = ''OV''; /* Nombre por defecto de la nueva serie */
            
            INSERT INTO fza_empresas_series (
                TIPODOC_SERIE,
                CODIGO_EMPRESA_SERIE,
                CODIGO_ALMACEN_SERIE,
                CODIGO_CAJA_SERIE,
                SERIE_SERIE,
                FECHA_DESDE_SERIE,
                FECHA_HASTA_SERIE
                /* Descomenta y ajusta si tu tabla tiene columnas de auditoría:
                , INSTANTEALTA,
                USUARIOALTA
                */
            ) VALUES (
                ''OV'',
                pEmpresa,
                pAlmacen,
                pCaja,
                vSerie,
                CURDATE(),
                NULL
                /*
                , CURRENT_TIMESTAMP,
                pUsuario
                */
            );
        END IF;

        /* 3. Crear fila de contador si no existe */        
        IF NOT EXISTS (
            SELECT 1              
              FROM fza_contadores             
             WHERE TIPODOC_CONTADOR = ''OV''               
               AND EMPRESA_CONTADOR = pEmpresa               
               AND SERIE_CONTADOR   = vSerie        
        ) THEN            
            INSERT INTO fza_contadores (
                TIPODOC_CONTADOR,
                EMPRESA_CONTADOR,
                SERIE_CONTADOR,
                CONTADOR_CONTADOR,
                NUMDIGIT_CONTADOR,
                ACTIVO_CONTADOR,
                DEFAULT_CONTADOR,
                INSTANTEALTA,
                USUARIOALTA,
                USUARIOMODIF)
            VALUES (
                ''OV'',
                pEmpresa,
                vSerie,
                1,
                8,
                ''S'',
                ''S'',
                CURRENT_TIMESTAMP,
                pUsuario,
                pUsuario);
        END IF;

        /* 4. Bloquear fila y leer dígitos */        
        SELECT NUMDIGIT_CONTADOR          
          INTO pPADD          
          FROM fza_contadores         
         WHERE TIPODOC_CONTADOR = ''OV''           
           AND EMPRESA_CONTADOR = pEmpresa           
           AND SERIE_CONTADOR   = vSerie         
         LIMIT 1           
           FOR UPDATE;

        /* 5. Incrementar */        
        UPDATE fza_contadores           
           SET CONTADOR_CONTADOR = CONTADOR_CONTADOR + 1,
               USUARIOMODIF      = pUsuario         
         WHERE TIPODOC_CONTADOR  = ''OV''           
           AND EMPRESA_CONTADOR  = pEmpresa           
           AND SERIE_CONTADOR    = vSerie;

        /* 6. Devolver serie y número formateado */        
        SET pSerie := vSerie;

        SELECT LPAD(CONTADOR_CONTADOR - 1, pPADD, ''0'')
          INTO pcont          
          FROM fza_contadores         
         WHERE TIPODOC_CONTADOR = ''OV''           
           AND EMPRESA_CONTADOR = pEmpresa           
           AND SERIE_CONTADOR   = vSerie         
         LIMIT 1;

    COMMIT;
END //

DELIMITER ;', '2026-04-02 20:03:14', '2026-04-02 20:03:04', 'Administrador', 'Administrador'),
