  ('122', NULL, 'DROP VIEW IF EXISTS `vi_articulos_tarifas`;
 
CREATE ALGORITHM=UNDEFINED VIEW `vi_articulos_tarifas` AS
WITH 
-- Paso 1: filas "lógicas" sobre las que la vista debe iterar.
--   - Si el artículo tiene SKUs activos -> una fila por SKU.
--   - Si NO tiene SKUs                  -> una fila con CODIGO_UNIDAD = ''''.
unidades AS (
    SELECT
        a.CODIGO_ARTICULO                AS CODIGO_ARTICULO,
        skus.CODIGO_UNIDAD_SKU           AS CODIGO_UNIDAD,
        skus.CODIGO_VAR_SKU              AS CODIGO_VAR_SKU,
        skus.ESACTIVO_SKU                AS ESACTIVO_SKU,
        ''S''                              AS TIENE_SKU
    FROM fza_articulos a
    JOIN fza_articulos_skus skus
      ON skus.CODIGO_ARTICULO_SKU = a.CODIGO_ARTICULO
     AND skus.ESACTIVO_SKU = ''S''
    UNION ALL
    SELECT
        a.CODIGO_ARTICULO,
        ''''                               AS CODIGO_UNIDAD,
        NULL                             AS CODIGO_VAR_SKU,
        NULL                             AS ESACTIVO_SKU,
        ''N''                              AS TIENE_SKU
    FROM fza_articulos a
    WHERE NOT EXISTS (
        SELECT 1 FROM fza_articulos_skus s
        WHERE s.CODIGO_ARTICULO_SKU = a.CODIGO_ARTICULO
          AND s.ESACTIVO_SKU = ''S''
    )
),
-- Paso 2: descripción legible del SKU concatenando sus valores de atributos.
--   Ej: "ROJO / L"  (vacío para artículos sin SKU).
sku_desc AS (
    SELECT
        sa.CODIGO_UNIDAD_SA AS CODIGO_UNIDAD,
        GROUP_CONCAT(av.VALOR_AV ORDER BY av.ORDEN_AV SEPARATOR '' / '') AS DESCRIPCION_SKU
    FROM fza_atributos_sku sa
    JOIN fza_atributos_valores av ON av.ID_VALOR_AV = sa.ID_VALOR_SA
    GROUP BY sa.CODIGO_UNIDAD_SA
)
SELECT
    -- Identificación
    u.CODIGO_ARTICULO                                         AS CODIGO_ARTICULO_TARIFA,
    u.CODIGO_UNIDAD                                           AS CODIGO_UNIDAD_TARIFA,
    t.CODIGO_TARIFA                                           AS CODIGO_TARIFA,
    t.NOMBRE_TARIFA                                           AS NOMBRE_TARIFA,
    -- PK del registro existente (si lo hay) -> útil para UPDATE/DELETE en cliente
    ts.CODIGO_UNICO_TARIFA                                    AS CODIGO_UNICO_TARIFA_SKU,
    tp.CODIGO_UNICO_TARIFA                                    AS CODIGO_UNICO_TARIFA_PADRE,
    -- CODIGO_UNICO_TARIFA "efectivo" (compatibilidad con código antiguo):
    --   el del SKU si existe, si no el del padre, si no NULL.
    COALESCE(ts.CODIGO_UNICO_TARIFA, tp.CODIGO_UNICO_TARIFA)  AS CODIGO_UNICO_TARIFA,
 
    -- Origen del precio
    CASE
        WHEN ts.CODIGO_UNICO_TARIFA IS NOT NULL THEN ''ESPECIFICO_SKU''
        WHEN tp.CODIGO_UNICO_TARIFA IS NOT NULL THEN ''HEREDADO_PADRE''
        ELSE ''SIN_PRECIO''
    END                                                       AS ORIGEN_PRECIO,
 
    -- Precios resueltos (SKU > padre > NULL)
    COALESCE(ts.PRECIOSALIDA_TARIFA, tp.PRECIOSALIDA_TARIFA)  AS PRECIOSALIDA_TARIFA,
    COALESCE(ts.PRECIOFINAL_TARIFA,  tp.PRECIOFINAL_TARIFA)   AS PRECIOFINAL_TARIFA,
    COALESCE(ts.PRECIO_DTO_TARIFA,   tp.PRECIO_DTO_TARIFA)    AS PRECIO_DTO_TARIFA,
    COALESCE(ts.PORCEN_DTO_TARIFA,   tp.PORCEN_DTO_TARIFA)    AS PORCEN_DTO_TARIFA,
 
    -- Vigencia (la del registro que aplica)
    COALESCE(ts.FECHA_DESDE_TARIFA, tp.FECHA_DESDE_TARIFA)    AS FECHA_DESDE_TARIFA,
    COALESCE(ts.FECHA_HASTA_TARIFA, tp.FECHA_HASTA_TARIFA)    AS FECHA_HASTA_TARIFA,
 
    -- Flags de tarifa y artículo
    t.ACTIVO_TARIFA                                           AS ACTIVO_TARIFA,
    t.ESIMP_INCL_TARIFA                                       AS ESIMP_INCL_TARIFA,
    t.ESDEFAULT_TARIFA                                        AS ESDEFAULT_TARIFA,
    a.DESCRIPCION_ARTICULO                                    AS DESCRIPCION_ARTICULO,
    a.TIPO_CANTIDAD_ARTICULO                                  AS TIPO_CANTIDAD_ARTICULO,
    a.ESVARIACION_ARTICULO                                    AS ESVARIACION_ARTICULO,
    iv.CODIGO_ABREVIATURA_TIPO_IVA                            AS TIPO_IVA_ARTICULO,
 
    -- Datos del SKU
    u.TIENE_SKU                                               AS TIENE_SKU,
    u.ESACTIVO_SKU                                            AS ESACTIVO_SKU,
    sd.DESCRIPCION_SKU                                        AS DESCRIPCION_SKU,
 
    -- Proveedor principal (igual que la vista anterior)
    ap.CODIGO_PROVEEDOR_ARTICULO_PROVEEDOR                    AS CODIGO_PROVEEDOR,
    p.RAZONSOCIAL_PROVEEDOR                                   AS RAZONSOCIAL_PROVEEDOR,
    ap.PRECIO_ULT_COMPRA_ARTICULO_PROVEEDOR                   AS PRECIO_ULT_COMPRA,
    ap.FECHA_VALIDEZ_ARTICULO_PROVEEDOR                       AS FECHA_VALIDEZ,
 
    -- Familia
    a.CODIGO_FAMILIA_ARTICULO                                 AS CODIGO_FAMILIA_ARTICULO,
    af.DESCRIPCION_FAMILIA                                    AS DESCRIPCION_FAMILIA,
 
    -- Nº atributos requeridos para validar SKU completo (igual que antes)
    (SELECT COUNT(DISTINCT va.ID_ATRIBUTO_VA)
       FROM fza_articulos_skus sk
       JOIN fza_variaciones_atributos va ON sk.CODIGO_VAR_SKU = va.ID_VA
      WHERE sk.CODIGO_ARTICULO_SKU = a.CODIGO_ARTICULO)       AS NUM_ATRIBUTOS_REQ,
 
    -- Auditoría: la del registro que aporta el precio (SKU si existe, si no padre).
    COALESCE(ts.INSTANTEMODIF, tp.INSTANTEMODIF)              AS INSTANTEMODIF,
    COALESCE(ts.INSTANTEALTA,  tp.INSTANTEALTA)               AS INSTANTEALTA,
    COALESCE(ts.USUARIOALTA,   tp.USUARIOALTA)                AS USUARIOALTA,
    COALESCE(ts.USUARIOMODIF,  tp.USUARIOMODIF)               AS USUARIOMODIF
 
FROM unidades u
JOIN fza_articulos a            ON a.CODIGO_ARTICULO = u.CODIGO_ARTICULO
-- Producto cartesiano contra todas las tarifas activas
JOIN fza_tarifas t              ON t.ACTIVO_TARIFA = ''S''
 
-- Tarifa específica del SKU (si existe) — solo vigentes hoy o futuras
LEFT JOIN fza_articulos_tarifas ts
       ON ts.CODIGO_ARTICULO_TARIFA = u.CODIGO_ARTICULO
      AND ts.CODIGO_UNIDAD_TARIFA   = u.CODIGO_UNIDAD
      AND ts.CODIGO_TARIFA          = t.CODIGO_TARIFA
      AND ts.ACTIVO_TARIFA          = ''S''
      AND u.CODIGO_UNIDAD <> ''''
      AND COALESCE(ts.FECHA_HASTA_TARIFA, ''9999-12-31'') >= CURDATE()
 
-- Tarifa "padre" (a nivel artículo, sin SKU) — solo vigentes hoy o futuras
LEFT JOIN fza_articulos_tarifas tp
       ON tp.CODIGO_ARTICULO_TARIFA = u.CODIGO_ARTICULO
      AND (tp.CODIGO_UNIDAD_TARIFA IS NULL OR tp.CODIGO_UNIDAD_TARIFA = '''')
      AND tp.CODIGO_TARIFA          = t.CODIGO_TARIFA
      AND tp.ACTIVO_TARIFA          = ''S''
      AND COALESCE(tp.FECHA_HASTA_TARIFA, ''9999-12-31'') >= CURDATE()
 
-- Resto de joins informativos (igual que la vista anterior)
LEFT JOIN fza_articulos_proveedores ap
       ON ap.CODIGO_ARTICULO_ARTICULO_PROVEEDOR = a.CODIGO_ARTICULO
      AND ap.ESPROVEEDORPRINCIPAL_ARTICULO_PROVEEDOR = ''S''
LEFT JOIN fza_proveedores p
       ON p.CODIGO_PROVEEDOR = ap.CODIGO_PROVEEDOR_ARTICULO_PROVEEDOR
LEFT JOIN fza_articulos_familias af
       ON af.CODIGO_FAMILIA = a.CODIGO_FAMILIA_ARTICULO
LEFT JOIN fza_ivas_tipos iv
       ON iv.CODIGO_ABREVIATURA_TIPO_IVA = a.TIPOIVA_ARTICULO
LEFT JOIN sku_desc sd
       ON sd.CODIGO_UNIDAD = u.CODIGO_UNIDAD
 
ORDER BY t.ORDEN_TARIFA, a.ORDEN_ARTICULO, u.CODIGO_UNIDAD;
 
