-- Tabla: fza_movimientos_almacen
DROP TABLE IF EXISTS fza_movimientos_almacen CASCADE;
CREATE TABLE fza_movimientos_almacen (
  NUMERO_MOV varchar(20) NOT NULL,
  TIPO_DOC_MOV varchar(5) NOT NULL,
  SERIE_DOC_MOV varchar(20) NOT NULL,
  NRO_DOC_MOV varchar(20) NOT NULL,
  LINEA_MOV varchar(4) NOT NULL,
  CODIGO_EMPRESA_MOV varchar(20) NOT NULL,
  CODIGO_ALMACEN_MOV varchar(10) NOT NULL,
  FECHA_MOV timestamp without time zone NULL DEFAULT NULL,
  CODIGO_ARTICULO_MOV varchar(20) NULL DEFAULT NULL,
  CODIGO_UNIDAD_MOV varchar(50) NOT NULL,
  DESCRIPCION_ARTICULO_MOV varchar(100) NULL DEFAULT NULL,
  TIPO_MOVIMIENTO_MOV varchar(1) NOT NULL,
  CANTIDAD_MOV numeric(19,6) NULL DEFAULT '0.000000',
  PRECIO_COSTE_UNITARIO_MOV numeric(19,6) NULL DEFAULT '0.000000',
  TOTAL_COSTE_MOV numeric(19,6) NULL DEFAULT '0.000000',
  PRECIO_MEDIO_MOV numeric(19,6) NULL DEFAULT '0.000000',
  CODIGO_ALMACEN_CONTRA_MOV varchar(10) NULL DEFAULT NULL,
  CODIGO_CLIENTE_MOV varchar(20) NULL DEFAULT NULL,
  CODIGO_PROVEEDOR_MOV varchar(20) NULL DEFAULT NULL,
  ESACTIVO_MOV varchar(1) NULL DEFAULT 'S',
  INSTANTEMODIF timestamp without time zone NOT NULL DEFAULT statement_timestamp(),
  INSTANTEALTA timestamp without time zone NOT NULL DEFAULT TIMESTAMP '1970-01-01 00:00:00',
  USUARIOALTA varchar(100) NOT NULL,
  USUARIOMODIF varchar(100) NOT NULL,
  TIPO_DOC_REF_MOV varchar(5) NULL DEFAULT NULL,
  SERIE_DOC_REF_MOV varchar(20) NULL DEFAULT NULL,
  NRO_DOC_REF_MOV varchar(20) NULL DEFAULT NULL,
  LINEA_REF_MOV varchar(4) NULL DEFAULT NULL,
  LOTE_MOV varchar(50) NULL DEFAULT '',
  FECHA_CADUCIDAD_MOV date NULL DEFAULT NULL,
  CODIGO_ALMACEN_DOC_MOV varchar(10) NULL DEFAULT NULL,
  NUMERO_OPERACION_DOC_MOV varchar(20) NULL DEFAULT NULL,
  CODIGO_CAJA_DOC_MOV varchar(10) NULL DEFAULT NULL,
  PRIMARY KEY (NUMERO_MOV)
);
CREATE INDEX idx_fecha_mov ON fza_movimientos_almacen (FECHA_MOV);
CREATE INDEX idx_mov_almacen_fecha ON fza_movimientos_almacen (CODIGO_ALMACEN_MOV, FECHA_MOV);
CREATE INDEX idx_mov_op_caja ON fza_movimientos_almacen (CODIGO_EMPRESA_MOV, CODIGO_ALMACEN_DOC_MOV, CODIGO_CAJA_DOC_MOV, NUMERO_OPERACION_DOC_MOV);
CREATE INDEX idx_mov_sku_fecha ON fza_movimientos_almacen (CODIGO_UNIDAD_MOV, FECHA_MOV);
CREATE INDEX idx_ref_mov ON fza_movimientos_almacen (TIPO_DOC_REF_MOV, SERIE_DOC_REF_MOV, NRO_DOC_REF_MOV, LINEA_REF_MOV);
CREATE INDEX idx_sku_alm_mov ON fza_movimientos_almacen (CODIGO_UNIDAD_MOV, CODIGO_ALMACEN_MOV, FECHA_MOV);
