  POBLACION_CLIENTE_FISCAL_PEDIDO varchar(200) NULL DEFAULT NULL,
  PROVINCIA_CLIENTE_FISCAL_PEDIDO varchar(200) NULL DEFAULT NULL,
  CPOSTAL_CLIENTE_FISCAL_PEDIDO varchar(15) NULL DEFAULT NULL,
