  TOTAL_IVAS_PEDIDO numeric(18,6) NULL DEFAULT NULL,
  PORCEN_RES_PEDIDO numeric(19,6) NULL DEFAULT NULL,
  TOTAL_RES_PEDIDO numeric(19,6) NULL DEFAULT NULL,
