  TOTAL_IMPUESTOS_PEDIDO numeric(18,6) NULL DEFAULT NULL,
  FORMA_PAGO_PEDIDO varchar(200) NULL DEFAULT NULL,
  PORCEN_RETENCION_PEDIDO numeric(19,6) NULL DEFAULT NULL,
