-- Tabla: fza_variaciones
DROP TABLE IF EXISTS fza_variaciones CASCADE;
CREATE TABLE fza_variaciones (
  CODIGO_VAR varchar(20) NOT NULL,
  NOMBRE_VAR varchar(100) NULL DEFAULT NULL,
  ESACTIVO_VAR varchar(1) NULL DEFAULT 'S',
  ORDEN_VAR integer NULL DEFAULT NULL,
  INSTANTEMODIF timestamp without time zone NOT NULL DEFAULT statement_timestamp(),
  INSTANTEALTA timestamp without time zone NOT NULL DEFAULT TIMESTAMP '1970-01-01 00:00:00',
  USUARIOALTA varchar(100) NOT NULL,
  USUARIOMODIF varchar(100) NOT NULL,
  PRIMARY KEY (CODIGO_VAR)
);
INSERT INTO fza_variaciones (CODIGO_VAR, NOMBRE_VAR, ESACTIVO_VAR, ORDEN_VAR, INSTANTEMODIF, INSTANTEALTA, USUARIOALTA, USUARIOMODIF) VALUES
  ('TC', 'TALLAS Y COLORES', 'S', 1, '2026-01-04 07:47:35', '2026-01-04 07:39:32', 'Administrador', 'Administrador');

-- Tabla: fza_variaciones_atributos
DROP TABLE IF EXISTS fza_variaciones_atributos CASCADE;
CREATE TABLE fza_variaciones_atributos (
  ID_VA varchar(20) NOT NULL,
  ID_ATRIBUTO_VA varchar(20) NOT NULL,
  NOMBRE_VA varchar(50) NULL DEFAULT NULL,
  ORDEN_VA integer NULL DEFAULT NULL,
  PRIMARY KEY (ID_VA,ID_ATRIBUTO_VA)
);
INSERT INTO fza_variaciones_atributos (ID_VA, ID_ATRIBUTO_VA, NOMBRE_VA, ORDEN_VA) VALUES
  ('TC', 'CO', 'Color', 1),
  ('TC', 'TAL', 'Talla', 2);

-- Tabla: fza_verifactu_eventos
DROP TABLE IF EXISTS fza_verifactu_eventos CASCADE;
CREATE TABLE fza_verifactu_eventos (
  ID_LOG bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  TIMESTAMP_LOG timestamp(3) without time zone NOT NULL,
  TIPO_EVENTO_LOG smallint NOT NULL CHECK (TIPO_EVENTO_LOG BETWEEN 0 AND 255),
  USUARIO_LOG varchar(100) NOT NULL,
  VERSION_LOG varchar(100) NOT NULL,
  DESCRIPCION_LOG text NOT NULL,
  DATOS_ADICIONALES_LOG text NULL DEFAULT NULL,
  HASH_ANTERIOR_LOG char(64) NOT NULL,
  HASH_PROPIO_LOG char(64) NOT NULL,
  FIRMA_DIGITAL_LOG char(64) NOT NULL,
  CREATED_AT_LOG timestamp without time zone NULL DEFAULT statement_timestamp(),
  NRO_FACTURA_LOG varchar(20) NULL DEFAULT NULL,
  SERIE_FACTURA_LOG varchar(20) NULL DEFAULT NULL,
  PRIMARY KEY (ID_LOG)
);
CREATE INDEX idx_hash_propio ON fza_verifactu_eventos (HASH_PROPIO_LOG);
CREATE INDEX idx_timestamp ON fza_verifactu_eventos (TIMESTAMP_LOG);
CREATE INDEX idx_tipo_evento ON fza_verifactu_eventos (TIPO_EVENTO_LOG);
CREATE INDEX idx_usuario ON fza_verifactu_eventos (USUARIO_LOG);

