-- ============================================================================
-- AJUSTE DE SECUENCIAS IDENTITY TRAS INSERTAR CLAVES EXPLÍCITAS
-- ============================================================================
SELECT setval(
  pg_get_serial_sequence('fza_articulos_tarifas', 'codigo_unico_tarifa'),
  COALESCE(MAX(CODIGO_UNICO_TARIFA), 1),
  MAX(CODIGO_UNICO_TARIFA) IS NOT NULL
) FROM fza_articulos_tarifas;
SELECT setval(
  pg_get_serial_sequence('fza_articulos_vinculos', 'id_vinculo'),
  COALESCE(MAX(ID_VINCULO), 1),
  MAX(ID_VINCULO) IS NOT NULL
) FROM fza_articulos_vinculos;
SELECT setval(
  pg_get_serial_sequence('fza_atributos_basicos', 'id_basico'),
  COALESCE(MAX(ID_BASICO), 1),
  MAX(ID_BASICO) IS NOT NULL
) FROM fza_atributos_basicos;
SELECT setval(
  pg_get_serial_sequence('fza_atributos_conjuntos', 'id_conjunto_ac'),
  COALESCE(MAX(ID_CONJUNTO_AC), 1),
  MAX(ID_CONJUNTO_AC) IS NOT NULL
) FROM fza_atributos_conjuntos;
SELECT setval(
  pg_get_serial_sequence('fza_atributos_valores', 'id_valor_av'),
  COALESCE(MAX(ID_VALOR_AV), 1),
  MAX(ID_VALOR_AV) IS NOT NULL
) FROM fza_atributos_valores;
SELECT setval(
  pg_get_serial_sequence('fza_atributos_valores_info', 'id_info'),
  COALESCE(MAX(ID_INFO), 1),
  MAX(ID_INFO) IS NOT NULL
) FROM fza_atributos_valores_info;
SELECT setval(
  pg_get_serial_sequence('fza_caja_operaciones', 'id_opcaja'),
  COALESCE(MAX(ID_OPCAJA), 1),
  MAX(ID_OPCAJA) IS NOT NULL
) FROM fza_caja_operaciones;
SELECT setval(
  pg_get_serial_sequence('fza_metadatos', 'codigo_metadato'),
  COALESCE(MAX(CODIGO_METADATO), 1),
  MAX(CODIGO_METADATO) IS NOT NULL
) FROM fza_metadatos;
SELECT setval(
  pg_get_serial_sequence('fza_propiedades_valores', 'id_valor_pv'),
  COALESCE(MAX(ID_VALOR_PV), 1),
  MAX(ID_VALOR_PV) IS NOT NULL
) FROM fza_propiedades_valores;
SELECT setval(
  pg_get_serial_sequence('fza_verifactu_eventos', 'id_log'),
  COALESCE(MAX(ID_LOG), 1),
  MAX(ID_LOG) IS NOT NULL
) FROM fza_verifactu_eventos;

