-- VISTAS
-- ============================================================================
CREATE OR REPLACE VIEW fza_caja_depositos_view AS
select 'ALTA' AS ROL_EN_OPERACION,d.ID_DEPOSITO_DEP AS ID_DEPOSITO_DEP,d.CODIGO_EMPRESA_DEP AS CODIGO_EMPRESA_OP,d.CODIGO_ALMACEN_DEP AS CODIGO_ALMACEN_OP,d.CODIGO_CAJA_DEP AS CODIGO_CAJA_OP,d.NUMERO_OPERACION_DEP AS NUMERO_OPERACION_OP,d.CODIGO_CLIENTE_DEP AS CODIGO_CLIENTE_DEP,d.CODIGO_ARTICULO_DEP AS CODIGO_ARTICULO_DEP,d.CODIGO_UNIDAD_DEP AS CODIGO_UNIDAD_DEP,d.CODIGO_ALMACEN_DEP AS CODIGO_ALMACEN_DEP,d.CANTIDAD_PENDIENTE_DEP AS CANTIDAD_PENDIENTE_DEP,d.PRECIO_VENTA_DEP AS PRECIO_VENTA_DEP,d.PORCEN_IVA_DEP AS PORCEN_IVA_DEP,d.IMPORTE_ANTICIPO_DEP AS IMPORTE_ANTICIPO_DEP,d.PRECIO_VENTA_DEP * d.CANTIDAD_PENDIENTE_DEP - d.IMPORTE_ANTICIPO_DEP AS IMPORTE_PENDIENTE_DEP,d.ESTADO_DEP AS ESTADO_DEP,d.FECHA_CREACION_DEP AS FECHA_CREACION_DEP,d.FECHA_ENTREGA_DEP AS FECHA_ENTREGA_DEP,d.EMPRESA_CANCEL_DEP AS EMPRESA_CANCEL_DEP,d.ALMACEN_CANCEL_DEP AS ALMACEN_CANCEL_DEP,d.CAJA_CANCEL_DEP AS CAJA_CANCEL_DEP,d.NUMERO_OPERACION_CANCEL_DEP AS NUMERO_OPERACION_CANCEL_DEP from fza_depositos_cliente d where d.NUMERO_OPERACION_DEP is not null and d.NUMERO_OPERACION_DEP <> '' union all select 'CANCELACION' AS CANCELACION,d.ID_DEPOSITO_DEP AS ID_DEPOSITO_DEP,d.EMPRESA_CANCEL_DEP AS EMPRESA_CANCEL_DEP,d.ALMACEN_CANCEL_DEP AS ALMACEN_CANCEL_DEP,d.CAJA_CANCEL_DEP AS CAJA_CANCEL_DEP,d.NUMERO_OPERACION_CANCEL_DEP AS NUMERO_OPERACION_CANCEL_DEP,d.CODIGO_CLIENTE_DEP AS CODIGO_CLIENTE_DEP,d.CODIGO_ARTICULO_DEP AS CODIGO_ARTICULO_DEP,d.CODIGO_UNIDAD_DEP AS CODIGO_UNIDAD_DEP,d.CODIGO_ALMACEN_DEP AS CODIGO_ALMACEN_DEP,d.CANTIDAD_PENDIENTE_DEP AS CANTIDAD_PENDIENTE_DEP,d.PRECIO_VENTA_DEP AS PRECIO_VENTA_DEP,d.PORCEN_IVA_DEP AS PORCEN_IVA_DEP,d.IMPORTE_ANTICIPO_DEP AS IMPORTE_ANTICIPO_DEP,d.PRECIO_VENTA_DEP * d.CANTIDAD_PENDIENTE_DEP - d.IMPORTE_ANTICIPO_DEP AS Name_exp_15,d.ESTADO_DEP AS ESTADO_DEP,d.FECHA_CREACION_DEP AS FECHA_CREACION_DEP,d.FECHA_ENTREGA_DEP AS FECHA_ENTREGA_DEP,d.EMPRESA_CANCEL_DEP AS EMPRESA_CANCEL_DEP,d.ALMACEN_CANCEL_DEP AS ALMACEN_CANCEL_DEP,d.CAJA_CANCEL_DEP AS CAJA_CANCEL_DEP,d.NUMERO_OPERACION_CANCEL_DEP AS NUMERO_OPERACION_CANCEL_DEP from fza_depositos_cliente d where d.NUMERO_OPERACION_CANCEL_DEP is not null and d.NUMERO_OPERACION_CANCEL_DEP <> '' union all select case o.TIPO_OPERACION_OPCAJA when 'DE' then 'COBRO_INICIAL' when 'CB' then 'COBRO_PARCIAL' end AS Name_exp_1,d.ID_DEPOSITO_DEP AS ID_DEPOSITO_DEP,o.CODIGO_EMPRESA_OPCAJA AS CODIGO_EMPRESA_OPCAJA,o.CODIGO_ALMACEN_OPCAJA AS CODIGO_ALMACEN_OPCAJA,o.CODIGO_CAJA_OPCAJA AS CODIGO_CAJA_OPCAJA,o.NUMERO_OPERACION_OPCAJA AS NUMERO_OPERACION_OPCAJA,d.CODIGO_CLIENTE_DEP AS CODIGO_CLIENTE_DEP,d.CODIGO_ARTICULO_DEP AS CODIGO_ARTICULO_DEP,d.CODIGO_UNIDAD_DEP AS CODIGO_UNIDAD_DEP,d.CODIGO_ALMACEN_DEP AS CODIGO_ALMACEN_DEP,d.CANTIDAD_PENDIENTE_DEP AS CANTIDAD_PENDIENTE_DEP,d.PRECIO_VENTA_DEP AS PRECIO_VENTA_DEP,d.PORCEN_IVA_DEP AS PORCEN_IVA_DEP,o.IMPORTE_TOTAL_OPCAJA AS IMPORTE_TOTAL_OPCAJA,d.PRECIO_VENTA_DEP * d.CANTIDAD_PENDIENTE_DEP - d.IMPORTE_ANTICIPO_DEP AS Name_exp_15,d.ESTADO_DEP AS ESTADO_DEP,d.FECHA_CREACION_DEP AS FECHA_CREACION_DEP,d.FECHA_ENTREGA_DEP AS FECHA_ENTREGA_DEP,d.EMPRESA_CANCEL_DEP AS EMPRESA_CANCEL_DEP,d.ALMACEN_CANCEL_DEP AS ALMACEN_CANCEL_DEP,d.CAJA_CANCEL_DEP AS CAJA_CANCEL_DEP,d.NUMERO_OPERACION_CANCEL_DEP AS NUMERO_OPERACION_CANCEL_DEP from (fza_caja_operaciones o join fza_depositos_cliente d on(d.ID_DEPOSITO_DEP = o.ID_DEPOSITO_OPCAJA)) where o.TIPO_OPERACION_OPCAJA in ('CB','DE') and o.ID_DEPOSITO_OPCAJA is not null;

CREATE OR REPLACE VIEW vi_articulos AS
select fza_articulos.CODIGO_ARTICULO AS CODIGO_ARTICULO,fza_articulos.ACTIVO_ARTICULO AS ACTIVO_ARTICULO,fza_articulos.ORDEN_ARTICULO AS ORDEN_ARTICULO,fza_articulos.DESCRIPCION_ARTICULO AS DESCRIPCION_ARTICULO,fza_articulos.ESVARIACION_ARTICULO AS ESVARIACION_ARTICULO,fza_articulos.ESTRAZABLE_ARTICULO AS ESTRAZABLE_ARTICULO,fza_articulos.TIPO_ARTICULO AS TIPO_ARTICULO,fza_articulos.TIPO_VARIACION_ARTICULO AS TIPO_VARIACION_ARTICULO,fza_articulos.CODIGO_FAMILIA_ARTICULO AS CODIGO_FAMILIA_ARTICULO,fza_articulos_familias.DESCRIPCION_FAMILIA AS DESCRIPCION_FAMILIA,fza_articulos_familias.NOMBRE_FAMILIA AS NOMBRE_FAMILIA,fza_articulos.TIPOIVA_ARTICULO AS TIPOIVA_ARTICULO,fza_ivas_tipos.NOMBRE_TIPO_IVA AS NOMBRE_TIPO_IVA,fza_articulos.ESACTIVO_FIJO_ARTICULO AS ESACTIVO_FIJO_ARTICULO,fza_articulos.TIPO_CANTIDAD_ARTICULO AS TIPO_CANTIDAD_ARTICULO,fza_proveedores.RAZONSOCIAL_PROVEEDOR AS RAZONSOCIAL_PROVEEDOR,fza_articulos.INSTANTEMODIF AS INSTANTEMODIF,fza_articulos.INSTANTEALTA AS INSTANTEALTA,fza_articulos.USUARIOALTA AS USUARIOALTA,fza_articulos.USUARIOMODIF AS USUARIOMODIF from ((((fza_articulos left join fza_articulos_familias on(fza_articulos.CODIGO_FAMILIA_ARTICULO = fza_articulos_familias.CODIGO_FAMILIA)) left join fza_articulos_proveedores on(fza_articulos.CODIGO_ARTICULO = fza_articulos_proveedores.CODIGO_ARTICULO_ARTICULO_PROVEEDOR and fza_articulos_proveedores.ESPROVEEDORPRINCIPAL_ARTICULO_PROVEEDOR = 'S')) left join fza_proveedores on(fza_articulos_proveedores.CODIGO_PROVEEDOR_ARTICULO_PROVEEDOR = fza_proveedores.CODIGO_PROVEEDOR)) left join fza_ivas_tipos on(fza_articulos.TIPOIVA_ARTICULO = fza_ivas_tipos.CODIGO_ABREVIATURA_TIPO_IVA));

CREATE OR REPLACE VIEW vi_articulos_conjuntos_slots AS
select a.CODIGO_ARTICULO AS CODIGO_ARTICULO_ACA,a.TIPO_VARIACION_ARTICULO AS ID_VARIACION_AC,va.ID_ATRIBUTO_VA AS ID_ATRIBUTO_ACA,coalesce(va.NOMBRE_VA,va.ID_ATRIBUTO_VA) AS NOMBRE_ATRIBUTO,va.ORDEN_VA AS ORDEN_ATRIBUTO,v.NOMBRE_VAR AS NOMBRE_VARIACION,aca.ID_CONJUNTO_ACA AS ID_CONJUNTO_ACA,ac.NOMBRE_AC AS NOMBRE_AC,ac.ID_ATRIBUTO_AC AS ID_ATRIBUTO_AC,coalesce(aca.ES_GENERACION_AUTO,'S') AS ES_GENERACION_AUTO,aca.INSTANTEMODIF AS INSTANTEMODIF,aca.INSTANTEALTA AS INSTANTEALTA,aca.USUARIOALTA AS USUARIOALTA,aca.USUARIOMODIF AS USUARIOMODIF from ((((fza_articulos a join fza_variaciones_atributos va on(va.ID_VA = a.TIPO_VARIACION_ARTICULO)) join fza_variaciones v on(v.CODIGO_VAR = a.TIPO_VARIACION_ARTICULO)) left join fza_articulos_conjuntos_asign aca on(aca.CODIGO_ARTICULO_ACA = a.CODIGO_ARTICULO and aca.ID_ATRIBUTO_ACA = va.ID_ATRIBUTO_VA)) left join fza_atributos_conjuntos ac on(ac.ID_CONJUNTO_AC = aca.ID_CONJUNTO_ACA)) where a.ESVARIACION_ARTICULO = 'S' and a.TIPO_VARIACION_ARTICULO is not null;

CREATE OR REPLACE VIEW vi_articulos_familias AS
select fza_articulos_familias.CODIGO_FAMILIA AS CODIGO_FAMILIA,fza_articulos_familias.ACTIVO_FAMILIA AS ACTIVO_FAMILIA,fza_articulos_familias.ORDEN_FAMILIA AS ORDEN_FAMILIA,fza_articulos_familias.ESDEFAULT_FAMILIA AS ESDEFAULT_FAMILIA,fza_articulos_familias.CODIGO_SUBFAMILIA AS CODIGO_SUBFAMILIA,fza_articulos_familias2.NOMBRE_FAMILIA AS NOMBRE_SUBFAMILIA,fza_articulos_familias.NOMBRE_FAMILIA AS NOMBRE_FAMILIA,fza_articulos_familias.DESCRIPCION_FAMILIA AS DESCRIPCION_FAMILIA,fza_articulos_familias.INSTANTEMODIF AS INSTANTEMODIF,fza_articulos_familias.INSTANTEALTA AS INSTANTEALTA,fza_articulos_familias.USUARIOALTA AS USUARIOALTA,fza_articulos_familias.USUARIOMODIF AS USUARIOMODIF from (fza_articulos_familias left join fza_articulos_familias fza_articulos_familias2 on(fza_articulos_familias.CODIGO_SUBFAMILIA = fza_articulos_familias2.CODIGO_FAMILIA));

CREATE OR REPLACE VIEW vi_articulos_familias_list AS
select fza_articulos_familias.CODIGO_FAMILIA AS CODIGO_FAMILIA,fza_articulos_familias.ACTIVO_FAMILIA AS ACTIVO_FAMILIA,fza_articulos_familias.ORDEN_FAMILIA AS ORDEN_FAMILIA,fza_articulos_familias.ESDEFAULT_FAMILIA AS ESDEFAULT_FAMILIA,fza_articulos_familias.CODIGO_SUBFAMILIA AS CODIGO_SUBFAMILIA,fza_articulos_familias.NOMBRE_FAMILIA AS NOMBRE_FAMILIA,fza_articulos_familias.DESCRIPCION_FAMILIA AS DESCRIPCION_FAMILIA,fza_articulos_familias.INSTANTEMODIF AS INSTANTEMODIF,fza_articulos_familias.INSTANTEALTA AS INSTANTEALTA,fza_articulos_familias.USUARIOALTA AS USUARIOALTA,fza_articulos_familias.USUARIOMODIF AS USUARIOMODIF from fza_articulos_familias where fza_articulos_familias.ACTIVO_FAMILIA = 'S';

CREATE OR REPLACE VIEW vi_articulos_list AS
select fza_articulos.CODIGO_ARTICULO AS CODIGO_ARTICULO,fza_articulos.ACTIVO_ARTICULO AS ACTIVO_ARTICULO,fza_articulos.ORDEN_ARTICULO AS ORDEN_ARTICULO,fza_articulos.DESCRIPCION_ARTICULO AS DESCRIPCION_ARTICULO,fza_articulos.CODIGO_FAMILIA_ARTICULO AS CODIGO_FAMILIA_ARTICULO,fza_articulos_familias.DESCRIPCION_FAMILIA AS DESCRIPCION_FAMILIA,fza_articulos.TIPOIVA_ARTICULO AS TIPOIVA_ARTICULO,fza_articulos.ESACTIVO_FIJO_ARTICULO AS ESACTIVO_FIJO_ARTICULO,fza_articulos.TIPO_CANTIDAD_ARTICULO AS TIPO_CANTIDAD_ARTICULO,fza_articulos_proveedores.CODIGO_PROVEEDOR_ARTICULO_PROVEEDOR AS CODIGO_PROVEEDOR,fza_proveedores.RAZONSOCIAL_PROVEEDOR AS RAZONSOCIAL_PROVEEDOR,fza_articulos.INSTANTEMODIF AS INSTANTEMODIF,fza_articulos.INSTANTEALTA AS INSTANTEALTA,fza_articulos.USUARIOALTA AS USUARIOALTA,fza_articulos.USUARIOMODIF AS USUARIOMODIF from (((fza_articulos left join fza_articulos_familias on(fza_articulos.CODIGO_FAMILIA_ARTICULO = fza_articulos_familias.CODIGO_FAMILIA)) left join fza_articulos_proveedores on(fza_articulos_proveedores.CODIGO_ARTICULO_ARTICULO_PROVEEDOR = fza_articulos.CODIGO_ARTICULO and fza_articulos_proveedores.ESPROVEEDORPRINCIPAL_ARTICULO_PROVEEDOR = 'S')) left join fza_proveedores on(fza_proveedores.CODIGO_PROVEEDOR = fza_articulos_proveedores.CODIGO_PROVEEDOR_ARTICULO_PROVEEDOR)) where fza_articulos.ACTIVO_ARTICULO = 'S';

CREATE OR REPLACE VIEW vi_articulos_propiedades_slots AS
select a.CODIGO_ARTICULO AS CODIGO_ARTICULO,fa.CODIGO_FAMILIA AS CODIGO_FAMILIA,p.CODIGO_PROPIEDAD AS CODIGO_PROPIEDAD,p.NOMBRE_PROPIEDAD AS NOMBRE_PROPIEDAD,p.TIPO_VALOR AS TIPO_VALOR,fa.ES_REQUERIDO AS ES_REQUERIDO,fa.ORDEN_MOSTRAR AS ORDEN_MOSTRAR,ap.ID_VALOR_PV AS ID_VALOR_PV,ap.VALOR_LIBRE AS VALOR_LIBRE,coalesce(pv.VALOR_PV,ap.VALOR_LIBRE) AS VALOR_FINAL_MOSTRAR from ((((fza_articulos a join fza_familias_atributos fa on(a.CODIGO_FAMILIA_ARTICULO = fa.CODIGO_FAMILIA)) join fza_propiedades p on(fa.CODIGO_PROPIEDAD = p.CODIGO_PROPIEDAD)) left join fza_articulos_propiedades ap on(a.CODIGO_ARTICULO = ap.CODIGO_ARTICULO and p.CODIGO_PROPIEDAD = ap.CODIGO_PROPIEDAD)) left join fza_propiedades_valores pv on(ap.ID_VALOR_PV = pv.ID_VALOR_PV));

CREATE OR REPLACE VIEW vi_articulos_proveedores AS
select fza_articulos_proveedores.CODIGO_PROVEEDOR_ARTICULO_PROVEEDOR AS CODIGO_PROVEEDOR,fza_proveedores.RAZONSOCIAL_PROVEEDOR AS RAZONSOCIAL_PROVEEDOR,fza_articulos_proveedores.REF_PROVEEDOR_ARTICULO_PROVEEDOR AS REF_PROVEEDOR_ARTICULO_PROVEEDOR,fza_articulos_proveedores.CODIGO_ARTICULO_ARTICULO_PROVEEDOR AS CODIGO_ARTICULO,fza_articulos_proveedores.PRECIO_ULT_COMPRA_ARTICULO_PROVEEDOR AS PRECIO_ULT_COMPRA,fza_articulos_proveedores.FECHA_VALIDEZ_ARTICULO_PROVEEDOR AS FECHA_VALIDEZ,fza_articulos_proveedores.ESPROVEEDORPRINCIPAL_ARTICULO_PROVEEDOR AS ESPROVEEDORPRINCIPAL,fza_articulos_proveedores.INSTANTEMODIF AS INSTANTEMODIF,fza_articulos_proveedores.INSTANTEALTA AS INSTANTEALTA,fza_articulos_proveedores.USUARIOALTA AS USUARIOALTA,fza_articulos_proveedores.USUARIOMODIF AS USUARIOMODIF from (fza_articulos_proveedores left join fza_proveedores on(fza_articulos_proveedores.CODIGO_PROVEEDOR_ARTICULO_PROVEEDOR = fza_proveedores.CODIGO_PROVEEDOR));

CREATE OR REPLACE VIEW vi_articulos_skus AS
select fza_articulos_skus.CODIGO_UNIDAD_SKU AS CODIGO_UNIDAD_SKU,fza_articulos_skus.CODIGO_ARTICULO_SKU AS CODIGO_ARTICULO_SKU,fza_articulos_skus.CODIGO_VAR_SKU AS CODIGO_VAR_SKU,fza_articulos_skus.ESACTIVO_SKU AS ESACTIVO_SKU,fza_articulos_skus.INSTANTEMODIF AS INSTANTEMODIF,fza_articulos_skus.INSTANTEALTA AS INSTANTEALTA,fza_articulos_skus.USUARIOALTA AS USUARIOALTA,fza_articulos_skus.USUARIOMODIF AS USUARIOMODIF from fza_articulos_skus;

CREATE OR REPLACE VIEW vi_articulos_skus_extendida AS
select sku.CODIGO_UNIDAD_SKU AS CODIGO_UNIDAD_SKU,sku.CODIGO_ARTICULO_SKU AS CODIGO_ARTICULO_SKU,sku.CODIGO_VAR_SKU AS CODIGO_VAR_SKU,sku.ESACTIVO_SKU AS ESACTIVO_SKU,cb.CODIGO_BARRAS_CB AS CODIGO_BARRAS_CB,coalesce(stk.STOCK_TOTAL,0) AS STOCK_TOTAL,sku.INSTANTEMODIF AS INSTANTEMODIF,sku.INSTANTEALTA AS INSTANTEALTA,sku.USUARIOALTA AS USUARIOALTA,sku.USUARIOMODIF AS USUARIOMODIF from ((fza_articulos_skus sku left join (select fza_codigos_barras.CODIGO_UNIDAD_CB AS CODIGO_UNIDAD_CB,max(fza_codigos_barras.CODIGO_BARRAS_CB) AS CODIGO_BARRAS_CB from fza_codigos_barras group by fza_codigos_barras.CODIGO_UNIDAD_CB) cb on(sku.CODIGO_UNIDAD_SKU = cb.CODIGO_UNIDAD_CB)) left join (select fza_articulos_stockactual.CODIGO_UNIDAD_STK AS CODIGO_UNIDAD_STK,sum(fza_articulos_stockactual.CANTIDAD_STK) AS STOCK_TOTAL from fza_articulos_stockactual group by fza_articulos_stockactual.CODIGO_UNIDAD_STK) stk on(sku.CODIGO_UNIDAD_SKU = stk.CODIGO_UNIDAD_STK));

CREATE OR REPLACE VIEW vi_articulos_tarifas AS
with unidades as (select a.CODIGO_ARTICULO AS CODIGO_ARTICULO,skus.CODIGO_UNIDAD_SKU AS CODIGO_UNIDAD,skus.CODIGO_VAR_SKU AS CODIGO_VAR_SKU,skus.ESACTIVO_SKU AS ESACTIVO_SKU,'S' AS TIENE_SKU from (fza_articulos a join fza_articulos_skus skus on(skus.CODIGO_ARTICULO_SKU = a.CODIGO_ARTICULO and skus.ESACTIVO_SKU = 'S')) union all select a.CODIGO_ARTICULO AS CODIGO_ARTICULO,'' AS CODIGO_UNIDAD,NULL AS CODIGO_VAR_SKU,NULL AS ESACTIVO_SKU,'N' AS TIENE_SKU from fza_articulos a where NOT EXISTS(select 1 from fza_articulos_skus s where s.CODIGO_ARTICULO_SKU = a.CODIGO_ARTICULO and s.ESACTIVO_SKU = 'S' limit 1)), sku_desc as (select sa.CODIGO_UNIDAD_SA AS CODIGO_UNIDAD,string_agg((av.VALOR_AV)::text, ' / ' ORDER BY av.ORDEN_AV ASC) AS DESCRIPCION_SKU from (fza_atributos_sku sa join fza_atributos_valores av on(av.ID_VALOR_AV = sa.ID_VALOR_SA)) group by sa.CODIGO_UNIDAD_SA)select u.CODIGO_ARTICULO AS CODIGO_ARTICULO_TARIFA,u.CODIGO_UNIDAD AS CODIGO_UNIDAD_TARIFA,t.CODIGO_TARIFA AS CODIGO_TARIFA,t.NOMBRE_TARIFA AS NOMBRE_TARIFA,ts.CODIGO_UNICO_TARIFA AS CODIGO_UNICO_TARIFA_SKU,tp.CODIGO_UNICO_TARIFA AS CODIGO_UNICO_TARIFA_PADRE,coalesce(ts.CODIGO_UNICO_TARIFA,tp.CODIGO_UNICO_TARIFA) AS CODIGO_UNICO_TARIFA,case when ts.CODIGO_UNICO_TARIFA is not null then 'ESPECIFICO_SKU' when tp.CODIGO_UNICO_TARIFA is not null then 'HEREDADO_PADRE' else 'SIN_PRECIO' end AS ORIGEN_PRECIO,coalesce(ts.PRECIOSALIDA_TARIFA,tp.PRECIOSALIDA_TARIFA) AS PRECIOSALIDA_TARIFA,coalesce(ts.PRECIOFINAL_TARIFA,tp.PRECIOFINAL_TARIFA) AS PRECIOFINAL_TARIFA,coalesce(ts.PRECIO_DTO_TARIFA,tp.PRECIO_DTO_TARIFA) AS PRECIO_DTO_TARIFA,coalesce(ts.PORCEN_DTO_TARIFA,tp.PORCEN_DTO_TARIFA) AS PORCEN_DTO_TARIFA,coalesce(ts.FECHA_DESDE_TARIFA,tp.FECHA_DESDE_TARIFA) AS FECHA_DESDE_TARIFA,coalesce(ts.FECHA_HASTA_TARIFA,tp.FECHA_HASTA_TARIFA) AS FECHA_HASTA_TARIFA,t.ACTIVO_TARIFA AS ACTIVO_TARIFA,t.ESIMP_INCL_TARIFA AS ESIMP_INCL_TARIFA,t.ESDEFAULT_TARIFA AS ESDEFAULT_TARIFA,a.DESCRIPCION_ARTICULO AS DESCRIPCION_ARTICULO,a.TIPO_CANTIDAD_ARTICULO AS TIPO_CANTIDAD_ARTICULO,a.ESVARIACION_ARTICULO AS ESVARIACION_ARTICULO,iv.CODIGO_ABREVIATURA_TIPO_IVA AS TIPO_IVA_ARTICULO,u.TIENE_SKU AS TIENE_SKU,u.ESACTIVO_SKU AS ESACTIVO_SKU,sd.DESCRIPCION_SKU AS DESCRIPCION_SKU,ap.CODIGO_PROVEEDOR_ARTICULO_PROVEEDOR AS CODIGO_PROVEEDOR,p.RAZONSOCIAL_PROVEEDOR AS RAZONSOCIAL_PROVEEDOR,ap.PRECIO_ULT_COMPRA_ARTICULO_PROVEEDOR AS PRECIO_ULT_COMPRA,ap.FECHA_VALIDEZ_ARTICULO_PROVEEDOR AS FECHA_VALIDEZ,a.CODIGO_FAMILIA_ARTICULO AS CODIGO_FAMILIA_ARTICULO,af.DESCRIPCION_FAMILIA AS DESCRIPCION_FAMILIA,(select count(distinct va.ID_ATRIBUTO_VA) from (fza_articulos_skus sk join fza_variaciones_atributos va on(sk.CODIGO_VAR_SKU = va.ID_VA)) where sk.CODIGO_ARTICULO_SKU = a.CODIGO_ARTICULO) AS NUM_ATRIBUTOS_REQ,coalesce(ts.INSTANTEMODIF,tp.INSTANTEMODIF) AS INSTANTEMODIF,coalesce(ts.INSTANTEALTA,tp.INSTANTEALTA) AS INSTANTEALTA,coalesce(ts.USUARIOALTA,tp.USUARIOALTA) AS USUARIOALTA,coalesce(ts.USUARIOMODIF,tp.USUARIOMODIF) AS USUARIOMODIF from (((((((((unidades u join fza_articulos a on(a.CODIGO_ARTICULO = u.CODIGO_ARTICULO)) join fza_tarifas t on(t.ACTIVO_TARIFA = 'S')) left join fza_articulos_tarifas ts on(ts.CODIGO_ARTICULO_TARIFA = u.CODIGO_ARTICULO and ts.CODIGO_UNIDAD_TARIFA = u.CODIGO_UNIDAD and ts.CODIGO_TARIFA = t.CODIGO_TARIFA and ts.ACTIVO_TARIFA = 'S' and u.CODIGO_UNIDAD <> '' and coalesce(ts.FECHA_HASTA_TARIFA,'9999-12-31') >= (statement_timestamp()::date))) left join fza_articulos_tarifas tp on(tp.CODIGO_ARTICULO_TARIFA = u.CODIGO_ARTICULO and (tp.CODIGO_UNIDAD_TARIFA is null or tp.CODIGO_UNIDAD_TARIFA = '') and tp.CODIGO_TARIFA = t.CODIGO_TARIFA and tp.ACTIVO_TARIFA = 'S' and coalesce(tp.FECHA_HASTA_TARIFA,'9999-12-31') >= (statement_timestamp()::date))) left join fza_articulos_proveedores ap on(ap.CODIGO_ARTICULO_ARTICULO_PROVEEDOR = a.CODIGO_ARTICULO and ap.ESPROVEEDORPRINCIPAL_ARTICULO_PROVEEDOR = 'S')) left join fza_proveedores p on(p.CODIGO_PROVEEDOR = ap.CODIGO_PROVEEDOR_ARTICULO_PROVEEDOR)) left join fza_articulos_familias af on(af.CODIGO_FAMILIA = a.CODIGO_FAMILIA_ARTICULO)) left join fza_ivas_tipos iv on(iv.CODIGO_ABREVIATURA_TIPO_IVA = a.TIPOIVA_ARTICULO)) left join sku_desc sd on(sd.CODIGO_UNIDAD = u.CODIGO_UNIDAD));

CREATE OR REPLACE VIEW vi_art_busquedas AS
select fza_articulos.CODIGO_ARTICULO AS CODIGO_ARTICULO,fza_articulos.ACTIVO_ARTICULO AS ACTIVO_ARTICULO,fza_articulos.DESCRIPCION_ARTICULO AS DESCRIPCION_ARTICULO,fza_articulos.CODIGO_FAMILIA_ARTICULO AS CODIGO_FAMILIA_ARTICULO,fza_articulos_familias.DESCRIPCION_FAMILIA AS DESCRIPCION_FAMILIA,fza_articulos_proveedores.CODIGO_PROVEEDOR_ARTICULO_PROVEEDOR AS CODIGO_PROVEEDOR,fza_proveedores.RAZONSOCIAL_PROVEEDOR AS RAZON_SOCIAL_PROVEEDOR,fza_articulos_proveedores.ESPROVEEDORPRINCIPAL_ARTICULO_PROVEEDOR AS ESPROVEEDORPRINCIPAL,fza_articulos_proveedores.PRECIO_ULT_COMPRA_ARTICULO_PROVEEDOR AS PRECIO_ULT_COMPRA,fza_articulos_tarifas.CODIGO_TARIFA AS CODIGO_TARIFA,fza_tarifas.NOMBRE_TARIFA AS NOMBRE_TARIFA,fza_articulos_tarifas.PRECIOSALIDA_TARIFA AS PRECIOSALIDA_TARIFA,fza_articulos_tarifas.PRECIO_DTO_TARIFA AS PRECIO_DTO_TARIFA,fza_articulos_tarifas.PORCEN_DTO_TARIFA AS PORCEN_DTO_TARIFA,fza_articulos_tarifas.PRECIOFINAL_TARIFA AS PRECIOFINAL_TARIFA,fza_articulos_tarifas.FECHA_DESDE_TARIFA AS FECHA_DESDE_TARIFA,fza_articulos_tarifas.FECHA_HASTA_TARIFA AS FECHA_HASTA_TARIFA,fza_tarifas.ESIMP_INCL_TARIFA AS ESIMP_INCL_TARIFA,fza_ivas_tipos.NOMBRE_TIPO_IVA AS NOMBRE_TIPO_IVA,fza_articulos.TIPOIVA_ARTICULO AS TIPOIVA_ARTICULO,fza_articulos.TIPO_CANTIDAD_ARTICULO AS TIPO_CANTIDAD_ARTICULO,fza_articulos.USUARIOMODIF AS USUARIOMODIF,fza_articulos.INSTANTEALTA AS INSTANTEALTA,fza_articulos.INSTANTEMODIF AS INSTANTEMODIF,fza_articulos.USUARIOALTA AS USUARIOALTA,fza_articulos.ESACTIVO_FIJO_ARTICULO AS ESACTIVO_FIJO_ARTICULO from ((((((fza_articulos left join fza_articulos_familias on(fza_articulos.CODIGO_FAMILIA_ARTICULO = fza_articulos_familias.CODIGO_FAMILIA)) left join fza_articulos_tarifas on(fza_articulos.CODIGO_ARTICULO = fza_articulos_tarifas.CODIGO_ARTICULO_TARIFA)) left join fza_tarifas on(fza_articulos_tarifas.CODIGO_TARIFA = fza_tarifas.CODIGO_TARIFA and fza_tarifas.ESDEFAULT_TARIFA = 'S')) left join fza_ivas_tipos on(fza_articulos.TIPOIVA_ARTICULO = fza_ivas_tipos.CODIGO_ABREVIATURA_TIPO_IVA)) left join fza_articulos_proveedores on(fza_articulos.CODIGO_ARTICULO = fza_articulos_proveedores.CODIGO_ARTICULO_ARTICULO_PROVEEDOR and fza_articulos_proveedores.ESPROVEEDORPRINCIPAL_ARTICULO_PROVEEDOR = 'S')) left join fza_proveedores on(fza_proveedores.CODIGO_PROVEEDOR = fza_articulos_proveedores.CODIGO_PROVEEDOR_ARTICULO_PROVEEDOR)) where fza_articulos.ACTIVO_ARTICULO = 'S';

CREATE OR REPLACE VIEW vi_atributos_nombres AS
select distinct ask.CODIGO_ARTICULO_SKU AS CODIGO_ARTICULO_PADRE,vat.ID_ATRIBUTO_VA AS ID_ATRIBUTO,vat.NOMBRE_VA AS NOMBRE_ATRIBUTO,vat.ORDEN_VA AS ORDEN_VISUAL_ATRIBUTO from (fza_articulos_skus ask join fza_variaciones_atributos vat on(vat.ID_VA = ask.CODIGO_VAR_SKU));

CREATE OR REPLACE VIEW vi_cajasdef AS
select e.CODIGO_EMPRESA AS Empresa,e.RAZONSOCIAL_EMPRESA AS NombreEmpresa,a.CODIGO_ALMACEN_ALM AS Almacen,a.NOMBRE_ALMACEN_ALM AS NombreAlmacén,c.CODIGO_CAJA_ALMCAJ AS Caja,c.DESCRIPCION_ALMCAJ AS NombreCaja from ((fza_empresas e join fza_almacenes a on(e.CODIGO_EMPRESA = a.CODIGO_EMPRESA_ALM)) join fza_almacenes_cajas c on(a.CODIGO_ALMACEN_ALM = c.CODIGO_ALMACEN_ALMCAJ)) where e.ACTIVO_EMPRESA = 'S' and a.ESACTIVO_ALM = 'S';

CREATE OR REPLACE VIEW vi_caja_busqueda_unificada AS
select a.CODIGO_ARTICULO AS INPUT_BUSQUEDA,'CODIGO' AS TIPO_COINCIDENCIA,a.CODIGO_ARTICULO AS CODIGO_PADRE,NULL AS CODIGO_SKU,a.DESCRIPCION_ARTICULO AS DESCRIPCION_ARTICULO,a.TIPO_ARTICULO AS TIPO_ARTICULO from fza_articulos a where a.ACTIVO_ARTICULO = 'S' union all select sku.CODIGO_UNIDAD_SKU AS INPUT_BUSQUEDA,'SKU' AS TIPO_COINCIDENCIA,a.CODIGO_ARTICULO AS CODIGO_PADRE,sku.CODIGO_UNIDAD_SKU AS CODIGO_SKU,a.DESCRIPCION_ARTICULO AS DESCRIPCION_ARTICULO,a.TIPO_ARTICULO AS TIPO_ARTICULO from (fza_articulos_skus sku join fza_articulos a on(sku.CODIGO_ARTICULO_SKU = a.CODIGO_ARTICULO)) where sku.ESACTIVO_SKU = 'S' union all select cb.CODIGO_BARRAS_CB AS INPUT_BUSQUEDA,'EAN' AS TIPO_COINCIDENCIA,a.CODIGO_ARTICULO AS CODIGO_PADRE,sku.CODIGO_UNIDAD_SKU AS CODIGO_SKU,a.DESCRIPCION_ARTICULO AS DESCRIPCION_ARTICULO,a.TIPO_ARTICULO AS TIPO_ARTICULO from ((fza_codigos_barras cb join fza_articulos_skus sku on(cb.CODIGO_UNIDAD_CB = sku.CODIGO_UNIDAD_SKU)) join fza_articulos a on(sku.CODIGO_ARTICULO_SKU = a.CODIGO_ARTICULO));

CREATE OR REPLACE VIEW vi_caja_tarifa_sku_articulos AS
select skus.CODIGO_UNIDAD_SKU AS CODIGO_UNIDAD_TARIFA,skus.CODIGO_ARTICULO_SKU AS CODIGO_ARTICULO,tarifas.CODIGO_TARIFA AS CODIGO_TARIFA,tarifas.NOMBRE_TARIFA AS NOMBRE_TARIFA,coalesce(tarifa_sku.PRECIOFINAL_TARIFA,tarifa_padre.PRECIOFINAL_TARIFA) AS PRECIOFINAL_TARIFA,coalesce(tarifa_sku.PRECIOSALIDA_TARIFA,tarifa_padre.PRECIOSALIDA_TARIFA) AS PRECIOSALIDA_TARIFA,coalesce(tarifa_sku.PORCEN_DTO_TARIFA,tarifa_padre.PORCEN_DTO_TARIFA) AS PORCEN_DTO_TARIFA,coalesce(tarifa_sku.PRECIO_DTO_TARIFA,tarifa_padre.PRECIO_DTO_TARIFA) AS PRECIO_DTO_TARIFA,case when tarifa_sku.PRECIOFINAL_TARIFA is not null then 'ESPECIFICO_SKU' else 'HEREDADO_PADRE' end AS ORIGEN_PRECIO,((articulos.DESCRIPCION_ARTICULO)::text || (' (')::text || (skus.CODIGO_UNIDAD_SKU)::text || (')')::text) AS DESCRIPCION_COMPLETA,tarifas.ESIMP_INCL_TARIFA AS ESIMP_INCL_TARIFA,articulos.TIPO_CANTIDAD_ARTICULO AS TIPO_CANTIDAD_ARTICULO,articulos.CODIGO_FAMILIA_ARTICULO AS CODIGO_FAMILIA_ARTICULO from (((((fza_articulos_skus skus join fza_articulos articulos on(skus.CODIGO_ARTICULO_SKU = articulos.CODIGO_ARTICULO)) join (select distinct fza_articulos_tarifas.CODIGO_ARTICULO_TARIFA AS CODIGO_ARTICULO_TARIFA,fza_articulos_tarifas.CODIGO_TARIFA AS CODIGO_TARIFA from fza_articulos_tarifas) t_existentes on(t_existentes.CODIGO_ARTICULO_TARIFA = articulos.CODIGO_ARTICULO)) join fza_tarifas tarifas on(tarifas.CODIGO_TARIFA = t_existentes.CODIGO_TARIFA)) left join fza_articulos_tarifas tarifa_sku on(skus.CODIGO_UNIDAD_SKU = tarifa_sku.CODIGO_UNIDAD_TARIFA and tarifas.CODIGO_TARIFA = tarifa_sku.CODIGO_TARIFA)) left join fza_articulos_tarifas tarifa_padre on(articulos.CODIGO_ARTICULO = tarifa_padre.CODIGO_ARTICULO_TARIFA and tarifas.CODIGO_TARIFA = tarifa_padre.CODIGO_TARIFA and (tarifa_padre.CODIGO_UNIDAD_TARIFA is null or tarifa_padre.CODIGO_UNIDAD_TARIFA = ''))) where skus.ESACTIVO_SKU = 'S' and (tarifa_sku.PRECIOFINAL_TARIFA is not null or tarifa_padre.PRECIOFINAL_TARIFA is not null);

CREATE OR REPLACE VIEW vi_caja_totalventas AS
select fza_facturas.FECHA_FACTURA AS FECHA,count(0) AS TOTAL_VENTAS,sum(fza_facturas.TOTAL_LIQUIDO_FACTURA) AS TOTAL_COBRADO from fza_facturas group by fza_facturas.FECHA_FACTURA;

CREATE OR REPLACE VIEW vi_caja_vales_ptes AS
select fza_caja_vales.CODIGO_VL AS codigo_vale,fza_caja_vales.PIN_SEGURIDAD_VL AS pin,fza_caja_vales.IMPORTE_NOMINAL_VL AS importe,fza_caja_vales.FECHA_EMISION_VL AS fecha_emision,fza_caja_vales.FECHA_CADUCIDAD_VL AS fecha_caducidad,fza_caja_vales.CODIGO_CAJA_EMI_VL AS caja,fza_caja_vales.CODIGO_ALMACEN_EMI_VL AS almacen,fza_caja_vales.NUMERO_OPERACION_EMI_VL AS num_operacion,fza_caja_vales.SERIE_FACTURA_EMI_VL AS serie_factura,fza_caja_vales.NRO_FACTURA_EMI_VL AS num_factura,fza_caja_vales.CODIGO_CLIENTE_VL AS cliente,fza_caja_vales.OBSERVACIONES_VL AS observaciones,((fza_caja_vales.FECHA_CADUCIDAD_VL)::date - DATE '0001-01-01' + 366) - (((statement_timestamp()::date))::date - DATE '0001-01-01' + 366) AS dias_hasta_caducidad from fza_caja_vales where fza_caja_vales.ESTADO_VL = 'PENDIENTE' and (fza_caja_vales.FECHA_CADUCIDAD_VL is null or fza_caja_vales.FECHA_CADUCIDAD_VL >= (statement_timestamp()::date));

CREATE OR REPLACE VIEW vi_clientes AS
