AS_FACTURA AS TOTAL_IVAS_FACTURA,fza_facturas.PORCEN_RES_FACTURA AS PORCEN_RES_FACTURA,fza_facturas.TOTAL_RES_FACTURA AS TOTAL_RES_FACTURA,fza_facturas.TOTAL_BASEI_IVAS_FACTURA AS TOTAL_BASEI_IVAS_FACTURA,fza_facturas.PORCEN_IVAE_FACTURA AS PORCEN_IVAE_FACTURA,fza_facturas.TOTAL_IVAE_FACTURA AS TOTAL_IVAE_FACTURA,fza_facturas.PORCEN_REE_FACTURA AS PORCEN_REE_FACTURA,fza_facturas.TOTAL_REE_FACTURA AS TOTAL_REE_FACTURA,fza_facturas.TOTAL_BASEI_IVAE_FACTURA AS TOTAL_BASEI_IVAE_FACTURA,fza_facturas.NRO_FACTURA_ABONO_FACTURA AS NRO_FACTURA_ABONO_FACTURA,fza_facturas.SERIE_FACTURA_ABONO_FACTURA AS SERIE_FACTURA_ABONO_FACTURA,fza_facturas.TEXTO_LEGAL_FACTURA_CLIENTE_FACTURA AS TEXTO_LEGAL_FACTURA_CLIENTE_FACTURA,fza_facturas.TEXTO_LEGAL_FACTURA_EMPRESA_FACTURA AS TEXTO_LEGAL_FACTURA_EMPRESA_FACTURA,fza_facturas.DOCUMENTO_FACTURA AS DOCUMENTO_FACTURA,fza_facturas.COMENTARIOS_FACTURA AS COMENTARIOS_FACTURA,fza_facturas.CONTADOR_LINEAS_FACTURA AS CONTADOR_LINEAS_FACTURA,fza_facturas.ESCREARARTICULOS_FACTURA AS ESCREARARTICULOS_FACTURA,fza_facturas.ESDESCRIPCIONES_AMP_FACTURA AS ESDESCRIPCIONES_AMP_FACTURA,fza_facturas.ESFECHADEENTREGA_FACTURA AS ESFECHADEENTREGA_FACTURA,fza_formas_pago.DESCRIPCION_FORMAPAGO AS DESCRIPCION_FORMAPAGO,fza_formas_pago.ESCONTADO_FORMAPAGO AS ESCONTADO_FORMAPAGO,(select string_agg(((' ')::text || (to_char(fza_recibos.FECHA_VENCIMIENTO_RECIBO, 'DD/MM/YYYY'))::text || ('=> ')::text || (to_char(fza_recibos.EUROS_RECIBO, 'FM999,999,999,999,999,990.00'))::text || ('€')::text)::text, ',') from fza_recibos where fza_recibos.NRO_FACTURA_RECIBO = fza_facturas.NRO_FACTURA and fza_recibos.SERIE_FACTURA_RECIBO = fza_facturas.SERIE_FACTURA) AS VENCIMIENTOS_RECIBOS,fza_empresas.IBAN_EMPRESA AS IBAN_EMPRESA,fza_clientes.IBAN_CLIENTE AS IBAN_CLIENTE,fza_formas_pago.ESVERBANCOEMPRESA_FORMAPAGO AS ESVERBANCOEMPRESA_FORMAPAGO from (((fza_facturas left join fza_formas_pago on(fza_facturas.FORMA_PAGO_FACTURA = fza_formas_pago.CODIGO_FORMAPAGO)) left join fza_empresas on(fza_facturas.CODIGO_EMPRESA_FACTURA = fza_empresas.CODIGO_EMPRESA)) left join fza_clientes on(fza_facturas.CODIGO_CLIENTE_FACTURA = fza_clientes.CODIGO_CLIENTE));

