CREATE OR REPLACE VIEW vi_fac_lin_busquedas AS
select fza_facturas_lineas.NRO_FACTURA_LINEA AS NRO_FACTURA_LINEA,fza_facturas_lineas.SERIE_FACTURA_LINEA AS SERIE_FACTURA_LINEA,fza_facturas_lineas.LINEA_FACTURA_LINEA AS LINEA_FACTURA_LINEA,fza_facturas_lineas.CODIGO_ARTICULO_FACTURA_LINEA AS CODIGO_ARTICULO_FACTURA_LINEA,fza_facturas_lineas.CODIGO_FAMILIA_FACTURA_LINEA AS CODIGO_FAMILIA_FACTURA_LINEA,fza_facturas_lineas.NOMBRE_FAMILIA_FACTURA_LINEA AS NOMBRE_FAMILIA_FACTURA_LINEA,fza_facturas_lineas.FECHA_ENTREGA_FACTURA_LINEA AS FECHA_ENTREGA_FACTURA_LINEA,fza_facturas_lineas.TIPO_CANTIDAD_ARTICULO_FACTURA_LINEA AS TIPO_CANTIDAD_ARTICULO_FACTURA_LINEA,fza_facturas_lineas.ESIMP_INCL_TARIFA_FACTURA_LINEA AS ESIMP_INCL_TARIFA_FACTURA_LINEA,fza_facturas_lineas.TIPOIVA_ARTICULO_FACTURA_LINEA AS TIPOIVA_ARTICULO_FACTURA_LINEA,fza_ivas_tipos.NOMBRE_TIPO_IVA AS NOMBRE_TIPO_IVA,fza_facturas_lineas.DESCRIPCION_ARTICULO_FACTURA_LINEA AS DESCRIPCION_ARTICULO_FACTURA_LINEA,fza_facturas_lineas.CODIGO_TARIFA_FACTURA_LINEA AS CODIGO_TARIFA_FACTURA_LINEA,fza_facturas_lineas.CANTIDAD_FACTURA_LINEA AS CANTIDAD_FACTURA_LINEA,fza_facturas_lineas.PRECIOSALIDA_FACTURA_LINEA AS PRECIOSALIDA_FACTURA_LINEA,fza_facturas_lineas.PORCEN_DTO_FACTURA_LINEA AS PORCEN_DTO_FACTURA_LINEA,fza_facturas_lineas.PRECIO_DTO_FACTURA_LINEA AS PRECIO_DTO_FACTURA_LINEA,fza_facturas_lineas.PRECIOVENTA_SIVA_ARTICULO_FACTURA_LINEA AS PRECIOVENTA_SIVA_ARTICULO_FACTURA_LINEA,fza_facturas_lineas.PORCEN_IVA_FACTURA_LINEA AS PORCEN_IVA_FACTURA_LINEA,fza_facturas_lineas.PRECIOVENTA_CIVA_ARTICULO_FACTURA_LINEA AS PRECIOVENTA_CIVA_ARTICULO_FACTURA_LINEA,fza_facturas_lineas.TOTAL_FACTURA_LINEA AS TOTAL_FACTURA_LINEA,fza_facturas_lineas.TOTAL_FACTURASIVA_LINEA AS TOTAL_FACTURASIVA_LINEA,fza_facturas.CODIGO_CLIENTE_FACTURA AS CODIGO_CLIENTE_FACTURA_LINEA,fza_facturas.CODIGO_EMPRESA_FACTURA AS CODIGO_EMPRESA_FACTURA_LINEA from ((fza_facturas_lineas left join fza_facturas on(fza_facturas_lineas.NRO_FACTURA_LINEA = fza_facturas.NRO_FACTURA and fza_facturas_lineas.SERIE_FACTURA_LINEA = fza_facturas.SERIE_FACTURA)) left join fza_ivas_tipos on(fza_facturas_lineas.TIPOIVA_ARTICULO_FACTURA_LINEA = fza_ivas_tipos.CODIGO_ABREVIATURA_TIPO_IVA));

CREATE OR REPLACE VIEW vi_formapago AS
select fza_formas_pago.CODIGO_FORMAPAGO AS CODIGO_FORMAPAGO,fza_formas_pago.ACTIVO_FORMAPAGO AS ACTIVO_FORMAPAGO,fza_formas_pago.ORDEN_FORMAPAGO AS ORDEN_FORMAPAGO,fza_formas_pago.DESCRIPCION_FORMAPAGO AS DESCRIPCION_FORMAPAGO,fza_formas_pago.N_PLAZOS_FORMAPAGO AS N_PLAZOS_FORMAPAGO,fza_formas_pago.N_DIAS_ENTRE_PLAZOS_FORMAPAGO AS N_DIAS_ENTRE_PLAZOS_FORMAPAGO,fza_formas_pago.PORCEN_ANTICIPO_FORMAPAGO AS PORCEN_ANTICIPO_FORMAPAGO,fza_formas_pago.ESVERBANCOEMPRESA_FORMAPAGO AS ESVERBANCOEMPRESA_FORMAPAGO,fza_formas_pago.ESDEFAULT_FORMAPAGO AS ESDEFAULT_FORMAPAGO,fza_formas_pago.INSTANTEMODIF AS INSTANTEMODIF,fza_formas_pago.INSTANTEALTA AS INSTANTEALTA,fza_formas_pago.USUARIOALTA AS USUARIOALTA,fza_formas_pago.USUARIOMODIF AS USUARIOMODIF from fza_formas_pago;

CREATE OR REPLACE VIEW vi_info_tpv_completa AS
select a.CODIGO_ARTICULO AS CODIGO_ARTICULO,a.DESCRIPCION_ARTICULO AS DESCRIPCION_ARTICULO,a.TIPO_ARTICULO AS TIPO_ARTICULO,a.ESTRAZABLE_ARTICULO AS TIENE_TRAZABILIDAD,(select count(0) from vi_atributos_nombres n where n.CODIGO_ARTICULO_PADRE = a.CODIGO_ARTICULO) AS NUM_ATRIBUTOS_REQ,(select n.NOMBRE_ATRIBUTO from vi_atributos_nombres n where n.CODIGO_ARTICULO_PADRE = a.CODIGO_ARTICULO and n.ORDEN_VISUAL_ATRIBUTO = 1 limit 1) AS ATTR1_NOMBRE,(select n.NOMBRE_ATRIBUTO from vi_atributos_nombres n where n.CODIGO_ARTICULO_PADRE = a.CODIGO_ARTICULO and n.ORDEN_VISUAL_ATRIBUTO = 2 limit 1) AS ATTR2_NOMBRE,(select n.NOMBRE_ATRIBUTO from vi_atributos_nombres n where n.CODIGO_ARTICULO_PADRE = a.CODIGO_ARTICULO and n.ORDEN_VISUAL_ATRIBUTO = 3 limit 1) AS ATTR3_NOMBRE,(select n.NOMBRE_ATRIBUTO from vi_atributos_nombres n where n.CODIGO_ARTICULO_PADRE = a.CODIGO_ARTICULO and n.ORDEN_VISUAL_ATRIBUTO = 4 limit 1) AS ATTR4_NOMBRE,(select n.NOMBRE_ATRIBUTO from vi_atributos_nombres n where n.CODIGO_ARTICULO_PADRE = a.CODIGO_ARTICULO and n.ORDEN_VISUAL_ATRIBUTO = 5 limit 1) AS ATTR5_NOMBRE from fza_articulos a;

CREATE OR REPLACE VIEW vi_ivas AS
select fza_ivas.CODIGO_IVA AS CODIGO_IVA,fza_ivas.GRUPO_ZONA_IVA AS GRUPO_ZONA_IVA,fza_ivas.DESCRIPCION_ZONA_IVA AS DESCRIPCION_ZONA_IVA,fza_ivas.PORCENEXENTO_IVA AS PORCENEXENTO_IVA,fza_ivas.PORCENEXENTO_RE_IVA AS PORCENEXENTO_RE_IVA,fza_ivas.PORCENNORMAL_IVA AS PORCENNORMAL_IVA,fza_ivas.PORCENNORMAL_RE_IVA AS PORCENNORMAL_RE_IVA,fza_ivas.PORCENREDUCIDO_IVA AS PORCENREDUCIDO_IVA,fza_ivas.PORCENREDUCIDO_RE_IVA AS PORCENREDUCIDO_RE_IVA,fza_ivas.PORCENSUPERREDUCIDO_IVA AS PORCENSUPERREDUCIDO_IVA,fza_ivas.PORCENSUPERREDUCIDO_RE_IVA AS PORCENSUPERREDUCIDO_RE_IVA,fza_ivas.FECHA_DESDE_IVA AS FECHA_DESDE_IVA,fza_ivas.FECHA_HASTA_IVA AS FECHA_HASTA_IVA,fza_ivas.INSTANTEMODIF AS INSTANTEMODIF,fza_ivas.INSTANTEALTA AS INSTANTEALTA,fza_ivas.USUARIOALTA AS USUARIOALTA,fza_ivas.USUARIOMODIF AS USUARIOMODIF,fza_ivas_grupos.ESAPLICA_RE_ZONA_IVA AS ESAPLICA_RE_ZONA_IVA,fza_ivas_grupos.ESIVAAGRICOLA_ZONA_IVA AS ESIVAAGRICOLA_ZONA_IVA,fza_ivas_grupos.ESDEFAULT_ZONA_IVA AS ESDEFAULT_ZONA_IVA,fza_ivas_grupos.ESIRPF_IMP_INCL_ZONA_IVA AS ESIRPF_IMP_INCL_ZONA_IVA,fza_ivas_grupos.PALABRA_REPORTS_ZONA_IVA AS PALABRA_REPORTS_ZONA_IVA from (fza_ivas join fza_ivas_grupos on(fza_ivas.GRUPO_ZONA_IVA = fza_ivas_grupos.GRUPO_ZONA_IVA));

CREATE OR REPLACE VIEW vi_ivas_empresa AS
select i.CODIGO_IVA AS CODIGO_IVA,i.GRUPO_ZONA_IVA AS GRUPO_ZONA_IVA,i.DESCRIPCION_ZONA_IVA AS DESCRIPCION_ZONA_IVA,i.PORCENEXENTO_IVA AS PORCENEXENTO_IVA,i.PORCENEXENTO_RE_IVA AS PORCENEXENTO_RE_IVA,i.PORCENNORMAL_IVA AS PORCENNORMAL_IVA,i.PORCENNORMAL_RE_IVA AS PORCENNORMAL_RE_IVA,i.PORCENREDUCIDO_IVA AS PORCENREDUCIDO_IVA,i.PORCENREDUCIDO_RE_IVA AS PORCENREDUCIDO_RE_IVA,i.PORCENSUPERREDUCIDO_IVA AS PORCENSUPERREDUCIDO_IVA,i.PORCENSUPERREDUCIDO_RE_IVA AS PORCENSUPERREDUCIDO_RE_IVA,i.FECHA_DESDE_IVA AS FECHA_DESDE_IVA,i.FECHA_HASTA_IVA AS FECHA_HASTA_IVA,ig.ESAPLICA_RE_ZONA_IVA AS ESAPLICA_RE_ZONA_IVA,ig.ESIVAAGRICOLA_ZONA_IVA AS ESIVAAGRICOLA_ZONA_IVA,ig.ESDEFAULT_ZONA_IVA AS ESDEFAULT_ZONA_IVA,em.CODIGO_EMPRESA AS CODIGO_EMPRESA,ig.ESIRPF_IMP_INCL_ZONA_IVA AS ESIRPF_IMP_INCL_ZONA_IVA,ig.PALABRA_REPORTS_ZONA_IVA AS PALABRA_REPORTS_ZONA_IVA from ((fza_ivas i join fza_ivas_grupos ig on(i.GRUPO_ZONA_IVA = ig.GRUPO_ZONA_IVA)) join fza_empresas em on(em.GRUPO_ZONA_IVA_EMPRESA = ig.GRUPO_ZONA_IVA));

