select fza_usuarios_perfiles.USUARIO_GRUPO_PERFILES AS USUARIO_GRUPO_PERFILES,fza_usuarios_perfiles.KEY_PERFILES AS KEY_PERFILES,fza_usuarios_perfiles.SUBKEY_PERFILES AS SUBKEY_PERFILES,fza_usuarios_perfiles.VALUE_PERFILES AS VALUE_PERFILES,fza_usuarios_perfiles.VALUE_TEXT_PERFILES AS VALUE_TEXT_PERFILES,fza_usuarios_perfiles.TYPE_BLOB_PERFILES AS TYPE_BLOB_PERFILES,fza_usuarios_perfiles.VALUE_BLOB_PERFILES AS VALUE_BLOB_PERFILES,fza_usuarios_perfiles.INSTANTEMODIF AS INSTANTEMODIF,fza_usuarios_perfiles.INSTANTEALTA AS INSTANTEALTA,fza_usuarios_perfiles.USUARIOALTA AS USUARIOALTA,fza_usuarios_perfiles.USUARIOMODIF AS USUARIOMODIF from fza_usuarios_perfiles;

CREATE OR REPLACE VIEW vi_variaciones AS
select fza_variaciones.CODIGO_VAR AS CODIGO_VAR,fza_variaciones.NOMBRE_VAR AS NOMBRE_VAR,fza_variaciones.ESACTIVO_VAR AS ESACTIVO_VAR,fza_variaciones.ORDEN_VAR AS ORDEN_VAR,fza_variaciones.INSTANTEMODIF AS INSTANTEMODIF,fza_variaciones.INSTANTEALTA AS INSTANTEALTA,fza_variaciones.USUARIOALTA AS USUARIOALTA,fza_variaciones.USUARIOMODIF AS USUARIOMODIF from fza_variaciones;

CREATE OR REPLACE VIEW v_articulos_stock_barras AS
select coalesce(s.CODIGO_UNIDAD_SKU,a.CODIGO_ARTICULO) AS SKU,a.DESCRIPCION_ARTICULO AS DESCRIPCION_ARTICULO,cb.CODIGO_BARRAS_CB AS CODIGO_BARRAS,coalesce(sum(stk.CANTIDAD_STK),0) AS STOCK_TOTAL from (((fza_articulos a left join fza_articulos_skus s on(a.CODIGO_ARTICULO = s.CODIGO_ARTICULO_SKU)) left join fza_codigos_barras cb on(cb.CODIGO_UNIDAD_CB = coalesce(s.CODIGO_UNIDAD_SKU,a.CODIGO_ARTICULO))) left join fza_articulos_stockactual stk on(stk.CODIGO_UNIDAD_STK = coalesce(s.CODIGO_UNIDAD_SKU,a.CODIGO_ARTICULO))) group by coalesce(s.CODIGO_UNIDAD_SKU,a.CODIGO_ARTICULO),a.DESCRIPCION_ARTICULO,cb.CODIGO_BARRAS_CB;

-- ============================================================================
-- RUTINAS
-- ============================================================================
-- Módulo: .routines_pg_batch_api.sql
-- ============================================================================
-- Factuzam: módulo PostgreSQL 16 de rutinas de API/consulta
-- Origen: bloque real de rutinas de factuzam_original.sql.
--
-- Contrato general:
--   * Los identificadores no se entrecomillan y PostgreSQL los normaliza a
--     minúsculas, igual que el resto del bootstrap convertido.
--   * Las rutinas con OUT/INOUT siguen siendo procedimientos y se invocan con
--     CALL. PostgreSQL devuelve sus OUT/INOUT como una fila; para un OUT puro
--     el llamador debe pasar NULL, por ejemplo:
--       CALL prc_get_data_articulo('ART-1', NULL, NULL);
--   * Las dos rutinas MariaDB que devolvían resultsets son funciones de tabla:
--       SELECT * FROM prc_busqueda_articulos(...);
--       SELECT * FROM prc_getperfilformulario(...);
--   * No hay START TRANSACTION/COMMIT internos. Cada CALL participa en la
--     transacción del llamador; los contadores se reservan con UPDATE ...
--     RETURNING y bloqueo de fila de PostgreSQL.
--   * statement_timestamp() reproduce el reloj por sentencia de MariaDB.
-- ============================================================================

-- Limpiar las firmas exactas para que este módulo sea repetible.
DROP FUNCTION IF EXISTS prc_busqueda_articulos(
  character varying, character varying, date, character varying, smallint, smallint
);
DROP FUNCTION IF EXISTS prc_getperfilformulario(
  character varying, character varying, character varying
);

DROP PROCEDURE IF EXISTS prc_agregar_valor_conjunto(
